import { displayGamePlanName } from "./game-player-capacity";
import { vpsTerm, vpsTermPriceCents, termPriceCents } from "./billing-terms";
import { extraDiskCentsAt } from "./extra-disk";
import { type BackupTier, backupTierMonthlyCents } from "./backup-tiers";
import { partnerDiscountCentsFor } from "./partner-discount";

/**
 * What one renewal costs — the SINGLE definition, used by every path that quotes
 * or charges one: the automatic sweep in worker/billing.ts, the saved-card path,
 * the "Renew now" button, the server page and the deploy wizard's term cards.
 *
 * WHY IT LIVES IN ITS OWN FILE. It used to sit in lib/stripe-cards.ts, which
 * imports the Stripe SDK and (transitively) nodemailer. The moment a CLIENT
 * component — the deploy wizard — needed the renewal price, that import chain
 * dragged `nodemailer/lib/dkim` into the browser bundle and the build failed with
 * "Can't resolve 'fs'". The pricing rule is pure arithmetic and has no business
 * carrying a mail transport with it, so it lives here with only the two tiny
 * modules it genuinely needs. lib/stripe-cards.ts re-exports it, so no server-side
 * caller had to change.
 *
 * The rule this file exists to enforce: there is ONE renewal formula. Two
 * incidents in one day came from a second copy — first a button that hardcoded
 * "+30 days" and the monthly price while the action charged a full term ($8.99
 * shown, $97.09 taken), then the shared quote written to fix it, which computed
 * from `plan.priceCents` and so ignored `gamePlan` and would have billed a $4.99
 * game server at its $8.99 base plan. Do not add a second formula.
 */
export type RenewalCharge = {
  months: number;
  /**
   * The amount to CHARGE / display — tax-INCLUSIVE (net + tax). When no
   * `taxRatePercent` is supplied (the default), tax is 0 and this equals `netCents`,
   * so every existing caller is unchanged. Because display and charge both read this
   * one field, `displayed === charged === renewed` holds by construction.
   */
  totalCents: number;
  /** The pre-tax subtotal (plan + IP + disk + backup). Invoice line items sum to this. */
  netCents: number;
  /** The VAT/GST added on top of `netCents` (Finding 1); 0 when no rate was passed. */
  taxCents: number;
  /** The rate (%) `taxCents` was computed at, recorded on the invoice. */
  taxRatePercent: number;
  /** The extra-root-disk portion, which gets its own invoice line. */
  extraDiskCents: number;
  extraDiskMonthlyCents: number;
  /** The paid backup-tier portion (Plus retention), which gets its own invoice line. */
  backupCents: number;
  backupMonthlyCents: number;
  /**
   * The dedicated-IP surcharge portion of `netCents` (0 unless
   * `dedicatedIpBillable`) — broken out as its OWN field (added 2026-09-26, purely
   * additive) so a caller can record it on `Invoice.dedicatedIpCents` for the
   * Creator Partner Program's commission rule (a dedicated IP add-on earns a
   * partner 0% commission — see lib/partner-commission.ts commissionableBaseCents).
   * Previously this amount was only ever folded into the combined subtotal with no
   * way to recover it after the fact.
   */
  ipCents: number;
  /**
   * How much of `netCents` was shaved off by a one-time RETENTION OFFER
   * (`PricedServer.pendingRenewalDiscountPercent`) on THIS renewal. 0 for every
   * server that never went through the cancel-flow retention offer (the
   * overwhelming majority) — existing callers that never read this field see no
   * behavior change. Exists so the invoice can show the discount as its own
   * line, the same way `extraDiskCents`/`backupCents` get their own lines,
   * instead of silently folding it into a smaller plan line.
   */
  retentionDiscountCents: number;
  /**
   * How much of `netCents` was shaved off by the CREATOR PARTNER PROGRAM's
   * permanent recurring discount (10% off every renewal, forever, once attached —
   * see lib/partner-discount.ts). 0 for every server owned by a customer not
   * attached to an active partner (the overwhelming majority) — existing callers
   * that never pass `RenewalPrices.partnerDiscountPercent` see zero behavior
   * change. Applied AFTER the one-time retention offer (if any), on whatever is
   * left, so the two discounts stack rather than double-count the same dollar.
   */
  partnerDiscountCents: number;
  /** The recurring rate `partnerDiscountCents` was computed at (0 when not attached). */
  partnerDiscountPercent: number;
  /** Human label for the invoice / receipt ("Nebula VPS" or the game plan name). */
  label: string;
  /**
   * What the renewal AFTER this one will charge (tax-inclusive, same maths): identical to
   * `totalCents` except when a one-time retention offer is discounting THIS renewal, in
   * which case it is the undiscounted figure. This is the "Renews at ..." price printed on
   * invoices (lib/invoice-renewal.ts). Computed by calling the SAME formula with the
   * one-time discount cleared, not by a second formula.
   */
  nextCycleTotalCents: number;
};

export type PricedServer = {
  termMonths: number;
  extraDiskGB: number;
  plan: { name: string; priceCents: number };
  gamePlan: { name: string; priceCents: number; termMonths: number } | null;
  dedicatedIp: unknown | null;
  /**
   * Did the customer actually choose/pay for this IP, vs. a VPS just being
   * handed one for free by the `dedicated_ip_default` platform setting? See the
   * IP surcharge lines below for why this has to gate the charge alongside
   * `dedicatedIp` itself.
   */
  wantsDedicatedIp: boolean;
  /** Paid backup retention tier. A full Server row supplies it; synthetic callers must pass it. */
  backupTier: BackupTier;
  /**
   * The ANNUAL discount FROZEN on this server at sale (`Server.annualDiscountPct`),
   * or null on a legacy/monthly/flat row. OPTIONAL so the many synthetic
   * `PricedServer` display/quote objects keep compiling; a full Server row supplies
   * it automatically. When present it WINS over the live `prices.annualDiscountPct`,
   * so an annual VPS / NxCloud / game server renews at exactly the rate it was
   * SOLD at even if the admin retunes the setting afterwards; null falls back to
   * the live rate, which for every non-annual term is identical maths.
   */
  annualDiscountPct?: number | null;
  /**
   * GRANDFATHER PROGRAM (2026-09-17): the plan/game-plan monthly rate FROZEN
   * on this server at sale (`Server.grandfatheredRenewalCents`), read here
   * INSTEAD OF the live `plan.priceCents` / `gamePlan.priceCents` when
   * present. OPTIONAL, same shape as `annualDiscountPct` above — every
   * existing synthetic `PricedServer` (wizard previews, tests) keeps
   * compiling and keeps pricing off the live catalog rate exactly as
   * before; only a real Server row (which supplies it automatically)
   * actually grandfathers anything. Null/undefined = price off the live
   * plan, which is correct for a legacy pre-program row that was never
   * backfilled AND for a free/admin server with no real price to freeze.
   */
  grandfatheredRenewalCents?: number | null;
  /**
   * RETENTION OFFER (2026-09-17 field, wired 2026-09-19): the one-time percent
   * FROZEN on this server's `pendingRenewalDiscountPercent` when a customer
   * accepted the "stay and save" cancel-flow offer (lib/actions-server-lifecycle.ts
   * claimRetentionOffer). Unlike `grandfatheredRenewalCents` (a permanent
   * per-month price override), this discounts exactly ONE upcoming renewal
   * charge and the caller is responsible for clearing it back to null once that
   * renewal actually commits (see worker/billing.ts commitRenewal and
   * lib/actions.ts renewNow) — `renewalCharge` itself only reads it, it never
   * decides when the discount has been "used up". OPTIONAL / null = no pending
   * discount, which is every server that has never gone through the retention
   * flow (and is therefore identical to today's behavior).
   */
  pendingRenewalDiscountPercent?: number | null;
};

/**
 * The admin-priced inputs a renewal is charged against. Every field is REQUIRED
 * deliberately, mirroring how the codebase guards renewal pricing everywhere else
 * (`termPromoPercent` is likewise required in lib/proration.ts): a call site that
 * builds this object cannot silently forget one and fall back to a stale default.
 */
export type RenewalPrices = {
  ipMonthlyCents: number;
  extraDiskPerGbCents: number;
  backupPlusCents: number;
  /**
   * The admin-configured ANNUAL discount (percent), resolved from the
   * `annual_discount_percent` setting via `annualDiscountPct()`.
   *
   * REQUIRED — not optional. A 12-month server renews at
   * `vpsTermPriceCents(price, 12, annualDiscountPct)`; if a call site could OMIT
   * this it would silently price annual at the shipped default (10%) while the
   * owner had set, say, 20% — the rate the customer was shown and charged at order.
   * Required turns that into a compile error at every one of the ~8 places that
   * build this object, so the annual setting cannot be forgotten on any renewal
   * path and `displayed === charged === renewed` holds.
   */
  annualDiscountPct: number;
  /**
   * OPTIONAL destination VAT/GST rate (percent) for the customer who owns this
   * server, resolved from their billing country (lib/tax.ts taxContextForUser).
   * Omitted / 0 => no tax added and `totalCents === netCents`, so every call site
   * that does not opt in is byte-for-byte unchanged. A charge site passes the
   * OWNER's rate so the wallet debit, the card leg and the invoice all agree; a
   * display of the owner's own renewal passes the SAME rate so the figure shown
   * equals the figure taken.
   */
  taxRatePercent?: number;
  /**
   * CREATOR PARTNER PROGRAM (2026-09-26): the customer's permanent RECURRING
   * discount percent (10 if attached to an active partner, 0 otherwise — resolved
   * by lib/partner-pricing.ts's `partnerDiscountForRenewal`, which always
   * collapses to the recurring tier since a renewal is never anyone's first
   * purchase). OPTIONAL, defaulting to 0 — every existing caller that doesn't
   * resolve/pass it keeps renewing at exactly today's price, byte-for-byte.
   */
  partnerDiscountPercent?: number;
};

export function renewalCharge(server: PricedServer, prices: RenewalPrices): RenewalCharge {
  const c = renewalChargeOnce(server, prices);
  const next =
    c.retentionDiscountCents > 0
      ? renewalChargeOnce({ ...server, pendingRenewalDiscountPercent: null }, prices)
      : c;
  return { ...c, nextCycleTotalCents: next.totalCents };
}

function renewalChargeOnce(
  server: PricedServer,
  prices: RenewalPrices,
): Omit<RenewalCharge, "nextCycleTotalCents"> {
  const isGame = !!server.gamePlan;
  // The term to renew — the customer's chosen `Server.termMonths` (1 = monthly,
  // 12 = annual). A game term is now a per-order choice (Monthly / Annual) just like
  // a VPS, so it rides the Server row, not the plan.
  //
  // VPS/NxCloud terms are always one of the 4 standard `VPS_TERMS`, so we normalise
  // through `vpsTerm`. A GAME server, however, may historically carry ANY term the
  // plan was configured with (a pre-existing game server was created with
  // `termMonths = gamePlan.termMonths`, which the admin can set 1..36). We therefore
  // read the game term back RAW (clamped >= 1) rather than through `vpsTerm`, whose
  // fallback would collapse a non-standard legacy value (say 3) to monthly and
  // change that server's renewal cadence. For the seeded games (all `termMonths: 1`)
  // and any new Monthly/Annual order this is identical to the standard path.
  const months = isGame ? Math.max(1, Math.round(server.termMonths)) : vpsTerm(server.termMonths).months;
  // The annual discount to price the term at: the rate FROZEN on the server at sale,
  // falling back to the live setting for legacy/monthly rows. Both halves resolve
  // the same number, so an annual sub renews at the sold rate.
  const annualPct = server.annualDiscountPct ?? prices.annualDiscountPct;
  // Extra root disk is billed EVERY cycle at the current per-GB price. Game plans
  // are a flat all-in price and never carry the add-on lines.
  const extraDiskMonthlyCents = isGame ? 0 : extraDiskCentsAt(server.extraDiskGB, prices.extraDiskPerGbCents);
  const extraDiskCents = extraDiskMonthlyCents * months;
  // Paid backup retention (Plus) rides alongside extra disk: billed every cycle at
  // the current admin price, and — like every add-on line — NOT carried by a game
  // plan (renewalCharge's game branch is flat all-in, so game servers are never
  // sold a paid backup tier; see lib/backup-upgrade.ts's game guard).
  const backupMonthlyCents = isGame ? 0 : backupTierMonthlyCents(server.backupTier, prices.backupPlusCents);
  const backupCents = backupMonthlyCents * months;
  // GRANDFATHER PROGRAM: the frozen rate wins over the live catalog price when
  // set (see PricedServer.grandfatheredRenewalCents's own doc comment) — this
  // is the ONE substitution point for both branches below, so a price rise on
  // the live Plan/GamePlan row never touches a server that already has a
  // frozen rate, while every other renewal-formula behavior (term math, annual
  // discount, add-ons) is completely unchanged.
  const grandfatheredPriceCents = server.grandfatheredRenewalCents ?? null;
  // A game plan's `priceCents` is its MONTHLY base (every seed is `termMonths: 1`).
  // Divide by the plan's own term so an admin plan configured as, say, a 3-month
  // bundle still yields a per-month rate; then price the customer's chosen term
  // through the SAME formula VPS uses. For a monthly game server this is exactly
  // `priceCents`; an ANNUAL game server renews at 12× that, less the annual discount.
  const gameMonthlyCents = isGame
    ? Math.round((grandfatheredPriceCents ?? server.gamePlan!.priceCents) / Math.max(1, server.gamePlan!.termMonths))
    : 0;
  // LEGACY GUARD. Game servers sold BEFORE terms existed carry no frozen annual rate
  // (`annualDiscountPct == null`) and always renewed at the plan's FLAT `priceCents`,
  // with no term discount ever applied. Preserve that exactly so no pre-existing game
  // server's renewal moves — only servers sold through the new term-aware flow (which
  // always stamps a frozen `annualDiscountPct`) are priced with `termPriceCents`.
  //
  // GUARD ON isGame FIRST. This value is only USED in the isGame branch below, but a
  // bare ternary evaluates it for EVERY server — and a VPS `PricedServer` (e.g. the one
  // the deploy wizard builds, `gamePlan: null`, no `annualDiscountPct`) then hits the
  // `annualDiscountPct == null` arm and dereferences `server.gamePlan!.priceCents` on a
  // null, crashing the whole deploy page with "Cannot read properties of null". Compute
  // 0 for non-game so the null is never touched.
  const gameTotalCents = !isGame
    ? 0
    : server.annualDiscountPct == null
      ? (grandfatheredPriceCents ?? server.gamePlan!.priceCents)
      : termPriceCents(gameMonthlyCents, months, annualPct);
  // Bill the IP surcharge only when the server BOTH actually holds a dedicated
  // IP AND the customer chose/paid for it (`wantsDedicatedIp`). Requiring
  // `dedicatedIp` alone used to mean two very different bugs at different times:
  // a NAT-fallback server (paid for an IP, pool was empty, never got one) being
  // charged for an IP it never received, and — found 2026-09-15 via a real
  // customer's admin profile showing a $2.99 "committed MRR" they never agreed
  // to — the opposite case: a VPS granted a dedicated IP for FREE by the
  // `dedicated_ip_default` platform setting (see worker/index.ts's provision())
  // being silently billed for it anyway on the next renewal. Requiring BOTH
  // flags fixes both directions: no charge without the address, no charge
  // without genuine customer intent to pay for it.
  const dedicatedIpBillable = !!server.dedicatedIp && server.wantsDedicatedIp;
  const ipCents = dedicatedIpBillable ? prices.ipMonthlyCents * months : 0;
  const preRetentionNetCents = isGame
    ? gameTotalCents + ipCents
    : vpsTermPriceCents(grandfatheredPriceCents ?? server.plan.priceCents, months, annualPct) +
      ipCents +
      extraDiskCents +
      backupCents;
  // RETENTION OFFER: a one-time percent-off THIS renewal only (see
  // PricedServer.pendingRenewalDiscountPercent's own doc comment). Applied to
  // the WHOLE pre-tax subtotal — plan plus every add-on line — because "50% off
  // your next renewal" is a single-event promise about the bill, not about one
  // line on it. Clamped 0..100 so a corrupt/out-of-range stored value can never
  // produce a negative charge or mint a discount beyond what was ever written
  // (claimRetentionOffer only ever writes 50). Applied BEFORE tax, matching
  // every other discount on this platform (coupons, promos) — the customer is
  // taxed on what they actually pay, not on the list price.
  const pendingDiscountPercent = Math.max(0, Math.min(100, server.pendingRenewalDiscountPercent ?? 0));
  const retentionDiscountCents =
    pendingDiscountPercent > 0 ? Math.round((preRetentionNetCents * pendingDiscountPercent) / 100) : 0;
  const afterRetentionCents = preRetentionNetCents - retentionDiscountCents;
  // CREATOR PARTNER PROGRAM: the customer's permanent 10%-off-every-renewal rate
  // (0 for the overwhelming majority never attached to a partner), applied to
  // whatever is left AFTER the one-time retention offer — the two stack rather
  // than either double-counting the same dollar or one silently cancelling the
  // other. Same clamp discipline as the retention percent above.
  const partnerDiscountPercent = Math.max(0, Math.min(100, prices.partnerDiscountPercent ?? 0));
  const partnerDiscountCents = partnerDiscountCentsFor(afterRetentionCents, partnerDiscountPercent);
  const netCents = afterRetentionCents - partnerDiscountCents;
  // VAT/GST on the pre-tax subtotal. Default rate 0 keeps `totalCents === netCents`
  // for every caller that does not pass the owner's rate (Finding 1).
  const taxRatePercent =
    Number.isFinite(prices.taxRatePercent) && (prices.taxRatePercent ?? 0) > 0 ? prices.taxRatePercent! : 0;
  const taxCents = Math.round((netCents * taxRatePercent) / 100);
  return {
    months,
    netCents,
    taxCents,
    taxRatePercent,
    totalCents: netCents + taxCents,
    extraDiskCents,
    extraDiskMonthlyCents,
    ipCents,
    partnerDiscountCents,
    partnerDiscountPercent,
    backupCents,
    backupMonthlyCents,
    retentionDiscountCents,
    // Display-time: no "/ 20 slots" in invoices/emails (Nxeon never caps players by plan).
    label: isGame ? displayGamePlanName(server.gamePlan!.name) : `${server.plan.name} VPS`,
  };
}
