async function notify(userId: string, title: string, body: string, href?: string) {
  try {
    await db.notification.create({ data: { userId, title, body, href } });
  } catch (e) {
    console.error("[billing] notification failed", e);
  }
}

/** The renewal queue, and the row shape every card/dunning helper below works on. */
async function dueServers(now: Date) {
  return db.server.findMany({
    where: {
      isFree: false,
      expiresAt: { lt: now },
      status: { in: ["RUNNING", "STOPPED"] },
    },
    include: { plan: true, user: true, gamePlan: true, dedicatedIp: true },
  });
}
export type DueServer = Awaited<ReturnType<typeof dueServers>>[number];

/**
 * Subscription sweep, run periodically by the worker:
 *  - expired + autoRenew, wallet covers it     -> charge wallet, extend the term
 *  - expired + autoRenew, wallet falls short   -> apply the credit, auto-charge the
 *                                                 saved card for the remainder
 *  - card declined                             -> dunning (retry days 1/3/5 + email)
 *  - retries exhausted, or no card past grace  -> queue SUSPEND with unpaid note
 * Free servers (isFree) are never touched.
 */
export async function billingSweep() {
  const now = new Date();
  const cfg = await dunningConfig();
  const prices = {
    ipMonthlyCents: await dedicatedIpMonthlyCents(), // admin setting; 0 = included
    // Per-GB/month price for extra ROOT DISK. Read once per sweep; every server that
    // bought extra storage renews at plan + (extraDiskGB x this) x months, so the
    // upsell keeps billing every cycle rather than being a one-off charge.
    extraDiskPerGbCents: await extraDiskPerGbCents(),
    // Monthly price of the Plus backup-retention tier. A server on Plus renews at
    // plan + this x months, folded into totalCents by renewalCharge exactly like
    // the extra-disk line, so the retention upsell keeps billing every cycle.
    backupPlusCents: await backupPlusMonthlyCents(),
    // The admin ANNUAL discount. A 12-month server renews at this rate — the same
    // one it was ordered and displayed at — so an annual subscription renews for
    // another year at the SAME annual price. Ignored for every other term.
    annualDiscountPct: await annualDiscountPct(),
  };
  // Seller country + global fallback rate, read ONCE per sweep. The per-server VAT
  // rate is resolved (purely) from each owner's billing country against these, so the
  // renewal charge, the card leg and the invoice all carry the same tax the customer
  // is shown elsewhere (Finding 1).
  const taxParams = { sellerCountry: await sellerCountry(), fallbackPercent: await taxRate() };
  // Off by default — see the setting's own doc comment in lib/settings.ts.
  const paypalFallbackEnabled = await getSettingBool("renewals_paypal_fallback_enabled", false);
  const taxCtxFor = (u: { billingCountry?: string | null; vatId?: string | null }): TaxContext =>
    resolveCountryTaxRate({
      country: u.billingCountry ?? null,
      vatId: u.vatId ?? null,
      sellerCountry: taxParams.sellerCountry,
      fallbackPercent: taxParams.fallbackPercent,
    });

  // Claim any card that was saved at Stripe but never confirmed in the browser,
  // BEFORE the renewal queries read card state — otherwise a customer who closed
  // the tab on Stripe's page gets dunned for a card we simply failed to record.
  try {
    const adopted = await adoptUnclaimedCards(now);
    if (adopted > 0) console.log(`[billing] adopted ${adopted} unconfirmed saved card(s)`);
  } catch (e) {
    console.error("[billing] card adoption error", e);
  }

  // Renewal warnings: notify once when a paid server is within 3 days of expiry
  const soon = new Date(now.getTime() + 3 * 86400_000);
  const upcoming = await db.server.findMany({
    where: {
      isFree: false,
      expiresAt: { gt: now, lt: soon },
      status: { in: ["RUNNING", "STOPPED"] },
    },
    include: { plan: true, user: true, gamePlan: true, dedicatedIp: true },
  });
  // A granted server on the EXPIRE policy never renews or charges, so "renews soon, top up" would be
  // false; the grant sweep (lib/partner-grants.ts) sends its own accurate 7-day / 1-day notices.
  const grantPolicies = await grantBillingFor(upcoming.map((s) => s.id));
  for (const server of upcoming) {
    if (isGrantFree(grantPolicies.get(server.id))) continue;
    // Tax-inclusive so the "renewal is $X" warning matches what the sweep will take.
    // Partner discount folded in too (Creator Partner Program) so a partner-
    // attached customer's warning shows the real 10%-off amount, not the list price.
    const partnerPct = (await partnerDiscountForRenewal(server.userId)).percent;
    const warnCents = renewalCharge(server, {
      ...prices,
      taxRatePercent: taxCtxFor(server.user).ratePercent,
      partnerDiscountPercent: partnerPct,
    }).totalCents;
    // A customer with a card (or, when enabled, a vaulted PayPal method) on
    // file needs no warning and no top-up: the renewal applies their wallet
    // credit and auto-charges the remainder. Telling them to "top up to avoid
    // suspension" would raise an alarm about a suspension that is not going
    // to happen.
    if (server.autoRenew && (server.user.balanceCents >= warnCents || hasChargeableRenewalMethod(server.user, paypalFallbackEnabled))) {
      continue;
    }
    const already = await db.notification.findFirst({
      where: {
        userId: server.userId,
        title: { contains: server.hostname },
        createdAt: { gt: new Date(now.getTime() - 4 * 86400_000) },
        AND: { title: { contains: "renews soon" } },
      },
    });
    if (!already) {
      await db.notification.create({
        data: {
          userId: server.userId,
          title: `${server.hostname} renews soon — action needed`,
          body: server.autoRenew
            ? `Renewal is $${(warnCents / 100).toFixed(2)} but your balance is $${(server.user.balanceCents / 100).toFixed(2)}. Top up to avoid suspension.`
            : `Auto-renew is off. Renew manually before ${server.expiresAt!.toISOString().slice(0, 10)} to avoid suspension.`,
          href: `/dashboard/servers/${server.id}`,
        },
      });
    }
  }
  const due = await dueServers(now);

  for (const server of due) {
    // One unhappy server must never abort the queue behind it. Every money write
    // below is individually guarded (CAS on expiresAt, UNIQUE on the payment intent
    // id, Stripe idempotency key), so continuing past a failure can only ever cost a
    // delayed renewal — never a duplicate charge. Without this, a single row with a
    // wedged Stripe customer would leave every later customer unrenewed AND
    // eventually suspended, for a fault that was entirely ours.
    try {
      await renewDueServer(server, { now, cfg, prices, taxParams, paypalFallbackEnabled });
    } catch (e) {
      console.error(`[billing] renewal pass failed for ${server.hostname}`, e);
    }
  }

  await terminateOverdue(now, cfg, prices, taxParams);
  await reapAbandonedSuspended(now, cfg);

  // Card housekeeping: nudge before a saved card expires, and honour the customer's
  // own automatic top-up preference. Both are isolated so a Stripe or SMTP problem
  // can never take the renewal sweep down with it.
  try {
    await cardExpirySweep(now);
  } catch (e) {
    console.error("[billing] card-expiry sweep error", e);
  }
  try {
    await autoRechargeSweep(now);
  } catch (e) {
    console.error("[billing] auto-recharge sweep error", e);
  }

  await domainAutoRenewSweep(now);

  // Poll in-flight inbound transfers on the same cadence as domain renewals —
  // domain upkeep all lives on one timer.
  try {
    await domainTransferInSweep(now);
  } catch (e) {
    console.error("[billing] domain transfer-in sweep error", e);
  }
}

/**
 * One expired server: renew it from wallet + card, or move it along the dunning
 * sequence, or suspend it once every promised attempt is spent.
 */
async function renewDueServer(
  server: DueServer,
  ctx: {
    now: Date;
    cfg: DunningConfig;
    prices: { ipMonthlyCents: number; extraDiskPerGbCents: number; backupPlusCents: number; annualDiscountPct: number };
    taxParams: { sellerCountry: string; fallbackPercent: number };
    paypalFallbackEnabled: boolean;
  },
) {
  const { now, cfg, taxParams, paypalFallbackEnabled } = ctx;
  // Resolve the owner's VAT/GST from their billing country (Finding 1) and fold it
  // into the renewal price so the wallet debit, any card leg and the invoice all
  // agree. Default rate 0 (no country on file) leaves this identical to before.
  const taxCtx = resolveCountryTaxRate({
    country: server.user.billingCountry ?? null,
    vatId: server.user.vatId ?? null,
    sellerCountry: taxParams.sellerCountry,
    fallbackPercent: taxParams.fallbackPercent,
  });
  // Creator Partner Program: 10% off every renewal, forever, once attached to an
  // ACTIVE partner (0 for the overwhelming majority of servers). See
  // lib/partner-pricing.ts and lib/renewal-charge.ts's own doc comment.
  const partnerPct = (await partnerDiscountForRenewal(server.userId)).percent;
  const prices = { ...ctx.prices, taxRatePercent: taxCtx.ratePercent, partnerDiscountPercent: partnerPct };
  const charge = renewalCharge(server, prices);
  const renewCents = charge.totalCents;
  const base = new Date(Math.max(server.expiresAt!.getTime(), now.getTime()));
  const newExpiry = addMonths(base, charge.months);

  await clearStaleDunning(server);

  let renewed = false;
  if (server.autoRenew) {
    // `server.user.balanceCents` came from a snapshot taken before this loop and
    // is stale as soon as the first renewal in this pass debits a wallet, so the
    // SPLIT is computed from a fresh read. It is still never a gate: `debitWallet`
    // re-checks funds atomically and the compare-and-swap on `expiresAt` stops a
    // concurrent renewNow()/second pass charging the same period twice.
    const fresh = await db.user.findUnique({
      where: { id: server.userId },
      select: { balanceCents: true },
    });
    const split = walletSplit({
      dueCents: renewCents,
      balanceCents: fresh?.balanceCents ?? 0,
      useWallet: true,
    });
    const cardInPlay = hasChargeableCard(server.user);
    const paypalInPlay = !cardInPlay && paypalFallbackEnabled && hasChargeablePayPal(server.user);

    if (split.cardCents === 0) {
      // Wallet covers the whole renewal — no card involved, no Stripe call.
      const outcome = await commitRenewal({ server, charge, newExpiry, taxCountry: taxCtx.country });
      renewed = outcome !== "insufficient";
      if (outcome === "renewed") {
        console.log(`[billing] renewed ${server.hostname} until ${newExpiry.toISOString()}`);
      }
    } else if (cardInPlay) {
      // Only attempt on the scheduled day. Without this gate a 10-minute sweep
      // would burn all three retries — and send all three emails — within half an
      // hour of the first decline.
      //
      // A scheduled time, once set, ALWAYS wins over the attempt counter, which buys
      // two things. `retryDunningNow` (fired when a customer saves a new card
      // mid-dunning) gets a real attempt even at the exhausted stage — refusing there
      // would suspend a customer whose brand-new card we never once tried. And the
      // exhausted stage's schedule points at the suspension day itself, so every
      // server gets one final, silent try at the card in the same pass that pauses it.
      const dueForRetry = server.dunningNextAt
        ? now >= server.dunningNextAt
        : server.dunningStage < DUNNING_EXHAUSTED;
      if (dueForRetry) {
        renewed = (
          await attemptCardRenewal({
            server,
            charge,
            cardCents: split.cardCents,
            newExpiry,
            now,
            cfg,
            taxCountry: taxCtx.country,
          })
        ).renewed;
      }
    } else if (paypalInPlay) {
      // Same scheduled-retry gate as the card path above — a PayPal-funded
      // customer gets the exact same dunning cadence, not an immediate try
      // every 10-minute sweep tick.
      const dueForRetry = server.dunningNextAt
        ? now >= server.dunningNextAt
        : server.dunningStage < DUNNING_EXHAUSTED;
      if (dueForRetry) {
        renewed = await attemptPayPalRenewal({
          server,
          charge,
          cardCents: split.cardCents,
          newExpiry,
          now,
          cfg,
          taxCountry: taxCtx.country,
        });
      }
    } else if (server.billingGraceUntil && now < server.billingGraceUntil) {
      // No chargeable card BECAUSE we retired one Stripe can never charge again
      // (or an admin granted grace). Not the decline ladder — the customer owes
      // us nothing but a fresh card — so run the re-add reminders instead and
      // leave suspension to the grace deadline below.
      await nudgeCardReadd({ server, cardCents: split.cardCents, now });
    } else {
      console.log(
        `[billing] ${server.hostname} short by ${fmtUsd(split.cardCents)} and no card on file — grace/suspend applies`,
      );
    }
  }

  if (renewed) {
    // nothing further this pass
  } else {
    const suspendAt = suspendDueAt(server, hasChargeableCard(server.user), cfg);
    if (suspendAt && now >= suspendAt) {
      await suspendUnpaid(server, cfg);
    }
  }
}

/**
 * The "re-add your card" ladder, run only while `Server.billingGraceUntil` is in
 * the future and the account has no chargeable card. Reuses the dunning
 * columns (free in this state: the decline ladder needs a card) — `dunningStage`
 * is the rung reached, `dunningNextAt` gates the next one:
 *
 *   rung 1  first notice   — sent by `retireUnusableCard` the moment the dead card is found
 *   rung 2  reminder       — CARD_READD_REMINDER_DAYS[0] (day 1) after the first notice
 *   rung 3  reminder       — CARD_READD_REMINDER_DAYS[1] (day 3)
 *   rung 4  final notice   — one day before `billingGraceUntil`, then nothing more
 *
 * Every rung reschedules at least MIN_RETRY_GAP_MS out, so a worker that was down
 * cannot fire the whole ladder in one afternoon. The customer saving a card ends
 * it: `hasChargeableCard` turns true, the normal card path runs, and
 * `commitRenewal` clears the grace and the stage together.
 */
async function nudgeCardReadd(opts: { server: DueServer; cardCents: number; now: Date }): Promise<void> {
  const { server, cardCents, now } = opts;
  const graceUntil = server.billingGraceUntil!;
  if (server.dunningNextAt && now < server.dunningNextAt) return; // not this rung's turn yet
  const finalAt = new Date(graceUntil.getTime() - DAY);

 * legitimately renew a little early (see the call site, `adminRenewServerNow`
 * in lib/actions.ts). `commitRenewal`'s own `Math.max(expiresAt, now)` base
 * and its CAS on the exact `expiresAt` read here make an early renewal exactly
 * as safe as a concurrent late one: two overlapping attempts (an admin
 * double-click, or an admin click racing the automatic sweep) can only ever
 * result in ONE of them actually charging and advancing the period — the
 * loser reports `alreadyRenewed`, never a second charge.
 */
export type ImmediateRenewalResult =
  | {
      ok: true;
      /** Which rail(s) actually paid this renewal. */
      path: "wallet" | "wallet+card" | "card";
      walletCents: number;
      cardCents: number;
      totalCents: number;
      newExpiry: Date;
      /** True when the card leg replayed an already-captured PaymentIntent (crash-safety idempotency, not a fresh charge). */
      cardReplayed?: boolean;
    }
  | {
      ok: false;
      reason: "insufficientFunds" | "declined" | "cardUnavailable" | "requiresAction" | "transient" | "alreadyRenewed";
      message: string;
      /** Present only for `reason: "declined"` — the issuer's own decline code, when Stripe supplied one. */
      code?: string;
    };

export async function renewServerImmediately(
  server: DueServer,
  ctx: {
    now: Date;
    cfg: DunningConfig;
    prices: { ipMonthlyCents: number; extraDiskPerGbCents: number; backupPlusCents: number; annualDiscountPct: number };
    /** Destination VAT/GST rate (percent) for the owner — e.g. from `taxContextForUser`. */
    taxRatePercent: number;
    /** Destination country the VAT was charged for; recorded on the invoice. */
    taxCountry?: string;
  },
): Promise<ImmediateRenewalResult> {
  const { now, cfg } = ctx;
  // Creator Partner Program: same 10%-off-every-renewal rate the sweep applies —
  // this path (renewNow / admin Renew now) must never charge a partner-attached
  // customer more than the automatic sweep would have.
  const partnerPct = (await partnerDiscountForRenewal(server.userId)).percent;
  const prices = { ...ctx.prices, taxRatePercent: ctx.taxRatePercent, partnerDiscountPercent: partnerPct };
  const charge = renewalCharge(server, prices);
  const renewCents = charge.totalCents;
  const base = new Date(Math.max(server.expiresAt!.getTime(), now.getTime()));
  const newExpiry = addMonths(base, charge.months);

  await clearStaleDunning(server);

  // Fresh balance read, exactly like `renewDueServer` — the row passed in may be
  // seconds or minutes stale by the time an admin actually confirms the charge.
  const fresh = await db.user.findUnique({ where: { id: server.userId }, select: { balanceCents: true } });
  const split = walletSplit({ dueCents: renewCents, balanceCents: fresh?.balanceCents ?? 0, useWallet: true });

  if (split.cardCents === 0) {
    const outcome = await commitRenewal({ server, charge, newExpiry, taxCountry: ctx.taxCountry });
    if (outcome === "renewed") {
      return { ok: true, path: "wallet", walletCents: renewCents, cardCents: 0, totalCents: renewCents, newExpiry };
    }
    if (outcome === "already") {
      return {
        ok: false,
        reason: "alreadyRenewed",
        message: "This server was renewed by another process a moment ago — refresh to see the new expiry.",
      };
    }
    // Only reachable if the balance changed between the fresh read above and the
    // guarded debit inside commitRenewal (a concurrent spend elsewhere on the same
    // account) — `walletSplit` just proved that SAME fresh read covers `renewCents`.
    return {
      ok: false,
      reason: "insufficientFunds",
      message: "The wallet balance changed before the charge completed — retry.",
    };
  }

  if (!hasChargeableCard(server.user)) {
    return {
      ok: false,
      reason: "insufficientFunds",
      message: `Wallet covers $${(split.walletApplied / 100).toFixed(2)} of the $${(renewCents / 100).toFixed(2)} due, and there is no chargeable card on file for the remaining $${(split.cardCents / 100).toFixed(2)}.`,
    };
  }

  const cardOutcome = await attemptCardRenewal({
    server,
    charge,
    cardCents: split.cardCents,
    newExpiry,
    now,
    cfg,
    taxCountry: ctx.taxCountry,
  });

  if (cardOutcome.renewed) {
    return {
      ok: true,
      path: split.walletApplied > 0 ? "wallet+card" : "card",
      walletCents: split.walletApplied,
      cardCents: cardOutcome.amountCents,
      totalCents: renewCents,
      newExpiry,
      cardReplayed: cardOutcome.replayed,
    };
  }

  switch (cardOutcome.kind) {
    case "declined":
      return { ok: false, reason: "declined", message: cardOutcome.message, code: cardOutcome.code };
    case "unavailable":
      return { ok: false, reason: "cardUnavailable", message: cardOutcome.message };
    case "requiresAction":
      return { ok: false, reason: "requiresAction", message: cardOutcome.message };
    case "walletDebitRaced":
    case "transient":
    default:
      return { ok: false, reason: "transient", message: cardOutcome.message };
  }
}

/**
 * Drop dunning state that belongs to a period we are no longer collecting for.
 *
 * `renewNow` (lib/actions.ts) advances `expiresAt` without touching the dunning
 * columns, so a customer who paid by hand halfway through a sequence carries a
 * stale `dunningStage` into the NEXT period — and the first decline of that fresh
 * period would arrive as "payment retry 2 declined, 1 attempt remaining", on a
 * compressed schedule, for a period they had never failed once.
 *
 * Every schedule this file writes lands at or after the expiry it was computed
 * from, so a `dunningNextAt` that predates the CURRENT `expiresAt` can only have
 * been written for an older, already-settled period.
 */
async function clearStaleDunning(server: DueServer): Promise<void> {
  if (server.dunningStage === 0 && !server.dunningNextAt && !server.dunningPayUrl) return;
  const belongsToThisPeriod = server.dunningNextAt && server.dunningNextAt >= server.expiresAt!;
  if (belongsToThisPeriod) return;

  await db.server.update({
    where: { id: server.id },
    data: { dunningStage: 0, dunningNextAt: null, dunningPayUrl: null },
  });
  // Keep the in-memory row honest: the rest of this pass reads these fields to
  // decide whether to charge, which email to send and when to suspend.
  server.dunningStage = 0;
  server.dunningNextAt = null;
  server.dunningPayUrl = null;
}

/* ------------------------------------------------------------------ *
 * Renewal commit (wallet) + card auto-charge
 * ------------------------------------------------------------------ */

/**
 * Advance the term and take the money from the wallet, atomically.
 *
 * This is the ONLY place a VPS renewal is granted, whether the wallet was funded
 * by a top-up, a referral credit or the saved card moments ago. One money path
 * means a partial failure can never half-apply a renewal: either the period
 * advances AND the wallet is debited AND the invoice exists, or none of it happened.
 *
 * The compare-and-swap on `expiresAt` is the idempotency guard. A retried sweep, a
 * second worker or a concurrent `renewNow` all read the same snapshot expiry; only
 * the first `updateMany` to match it writes, and every loser rolls back its debit
 * and its invoice with the transaction. Zero rows matched = someone else already
 * renewed this period, which is a success for us, not an error.
 */
async function commitRenewal(opts: {
  server: DueServer;
  charge: RenewalCharge;
  newExpiry: Date;
  /** Destination country the VAT was charged for (Finding 1); recorded on the invoice. */
  taxCountry?: string;
}): Promise<"renewed" | "insufficient" | "already"> {
  const { server, charge, newExpiry, taxCountry } = opts;
  // Captured from the in-tx invoice.create so the renewal invoice can be emailed
  // (with its PDF) only after the CAS-guarded tx commits — a rolled-back / already-
  // renewed sweep leaves this null and emails nothing.
  let renewedInvoice: { id: string; number: number; amountCents: number } | null = null;
  const renewCents = charge.totalCents;
  const {
    netCents,
    taxCents,
    taxRatePercent,
    extraDiskCents,
    extraDiskMonthlyCents,
    backupCents,
    backupMonthlyCents,
    ipCents,
    retentionDiscountCents,
    partnerDiscountCents,
    partnerDiscountPercent,
  } = charge;
  const periodStart = server.expiresAt!;
  // The pre-discount plan+add-on subtotal, so the invoice's base line can show
  // the real list price and the retention discount can get its OWN negative
  // line beneath it — same reasoning as the extra-disk/backup lines: a
  // customer should be able to see exactly what was discounted, not just a
  // smaller total with no explanation. Both discounts (retention, then partner)
  // are added back to reach the true pre-discount subtotal.
  const preRetentionNetCents = netCents + retentionDiscountCents + partnerDiscountCents;

  // `renewalCharge` bills `vpsTermPriceCents` (or a game plan's flat price) with NO
  // seasonal promo — renewals never get the intro discount, exactly as
  // lib/promotions.ts promises. So the months this renewal adds were sold at 0% off
  // and the term's stored rate basis must say so, or a later downgrade credits them
  // at a promo rate nobody was ever charged. Blended rather than overwritten for the
  // same reason as renewNow: this sweep only fires on already-expired servers (so
  // the blend is 0 in practice), but the shared helper means the two renewal paths
  // cannot express different rules for the same event.
  const renewedPercent = prorateBlendPercent({
    currentPercent: resolveTermPromoPercent(server.termPromoPercent),
    currentMonths: remainingMonths(server.expiresAt, Date.now()),
    addedPercent: 0,
    addedMonths: charge.months,
  });

  try {
    await db.$transaction(async (tx) => {
      const advanced = await tx.server.updateMany({
        where: { id: server.id, expiresAt: server.expiresAt },
        data: {
          expiresAt: newExpiry,
          termPromoPercent: renewedPercent,
          // The period is paid, so the collection state that belonged to it dies
          // with it. Leaving a stage behind would hand the NEXT period a
          // half-spent retry budget and the wrong dunning email.
          dunningStage: 0,
          dunningNextAt: null,
          dunningPayUrl: null,
          // The platform-fault grace belonged to the period just paid for.
          billingGraceUntil: null,
          // RETENTION OFFER: this renewal is the "very next" one the discount was
          // promised for — spent or not (retentionDiscountCents is 0 on every
          // server that never had one pending), it is cleared HERE, in the same
          // CAS-guarded write that advances the period, so it can never silently
          // reapply to the period after this one. A losing/replayed pass matches
          // zero rows (the `where: expiresAt: server.expiresAt` guard) and clears
          // nothing, so a retried sweep can't burn the discount without actually
          // renewing.
          pendingRenewalDiscountPercent: null,
        },
      });
      if (advanced.count === 0) throw new AlreadyRenewedError();
      await debitWallet(tx, server.userId, renewCents);
      await tx.walletTransaction.create({
        data: {
          userId: server.userId,
          amountCents: -renewCents,
          description: `Renewal: ${charge.label} (${server.hostname})`,
        },
      });
      // PAID invoice for this renewal period. Inside the CAS-guarded tx, so a
      // retried/concurrent sweep hits AlreadyRenewedError and rolls back —
      // never producing a second invoice for the same period.
      const renewalInvoice = await tx.invoice.create({
        data: invoiceCreateData({
          userId: server.userId,
          description: `Renewal: ${charge.label} (${server.hostname})`,
          status: "PAID",
          // Snapshot the card on file at charge time (null-safe for wallet-only users).
          paidBrand: server.user.cardBrand ?? null,
          paidLast4: server.user.cardLast4 ?? null,
          // VAT recorded separately; the line items below sum to the NET (netCents).
          taxCents,
          taxRatePercent,
          taxCountry: taxCountry ?? null,
          // Creator Partner Program commission math (lib/partner-commission.ts)
          // needs a real typed number for the dedicated-IP portion of this
          // invoice — never inferred from `lineItems` after the fact.
          dedicatedIpCents: ipCents,
          period: { start: periodStart, end: newExpiry },
          // Renewal snapshot: what the NEXT renewal charges (same formula, via
          // charge.nextCycleTotalCents), the term, and the new due date.
          renewal: { serverId: server.id, renewalCents: charge.nextCycleTotalCents, renewalTermMonths: charge.months, renewalDate: newExpiry },
          // Extra disk gets its OWN line so the customer sees exactly what the
          // permanent storage costs each cycle; the lines sum back to netCents.
          lineItems: [
            {
              description: `${charge.label} — ${server.hostname}`,
              qty: 1,
              unitCents: preRetentionNetCents - extraDiskCents - backupCents - ipCents,
              amountCents: preRetentionNetCents - extraDiskCents - backupCents - ipCents,
            },
            // Dedicated IP gets its own line too (2026-09-26) — previously folded
            // silently into the base line above; now consistent with how the
            // NEW-order invoice (lib/order.ts placeOrder) has always itemised it.
            // Total is unchanged either way.
            ...(ipCents > 0
              ? [
                  {
                    description: `Dedicated IP — ${server.hostname} ($${(ipCents / Math.max(1, charge.months) / 100).toFixed(2)}/mo)`,
                    qty: 1,
                    unitCents: ipCents,
                    amountCents: ipCents,
                  },
                ]
              : []),
            ...(extraDiskCents > 0
              ? [
                  {
                    description: `${extraDiskLabel(server.extraDiskGB)} — ${server.hostname} (permanent, $${(extraDiskMonthlyCents / 100).toFixed(2)}/mo)`,
                    qty: 1,
                    unitCents: extraDiskCents,
                    amountCents: extraDiskCents,
                  },
                ]
              : []),
            // Paid backup retention (Plus) gets its own line, mirroring extra disk,
            // so the customer sees exactly what the retention upsell costs each cycle.
            ...(backupCents > 0
              ? [
                  {
                    description: `Plus backups (keep 7) — ${server.hostname} ($${(backupMonthlyCents / 100).toFixed(2)}/mo)`,
                    qty: 1,
                    unitCents: backupCents,
                    amountCents: backupCents,
                  },
                ]
              : []),
            // The one-time retention offer, its OWN (negative) line so the customer
            // sees exactly what "stay and save" bought them on this one renewal —
            // never on any other, since `pendingRenewalDiscountPercent` was just
            // cleared above.
            ...(retentionDiscountCents > 0
              ? [
                  {
                    description: `Retention offer — 50% off this renewal (${server.hostname})`,
                    qty: 1,
                    unitCents: -retentionDiscountCents,
                    amountCents: -retentionDiscountCents,
                  },
                ]
              : []),
            // Creator Partner Program: the customer's permanent recurring
            // discount, its own (negative) line so they can see exactly what
            // being attached to a partner is saving them on every renewal.
            ...(partnerDiscountCents > 0
              ? [
                  {
                    description: `Partner discount — ${partnerDiscountPercent}% off (${server.hostname})`,
                    qty: 1,
                    unitCents: -partnerDiscountCents,
                    amountCents: -partnerDiscountCents,
                  },
                ]
              : []),
          ],
        }),
      });
      renewedInvoice = {
        id: renewalInvoice.id,
        number: renewalInvoice.number,
        amountCents: renewalInvoice.amountCents,
      };
      await tx.auditLog.create({
        data: { userId: server.userId, action: "billing.renewed", detail: server.id },
      });
      // First-month-free conversion: this is the server's SECOND term. Flip the
      // redemption anchored to it to renewed (idempotent, same tx as the money).
      await markPromoRenewed(tx, server.id);
    });
  } catch (e) {
    if (e instanceof InsufficientBalanceError) {
      console.log(`[billing] insufficient balance for ${server.hostname} — falling through to grace/suspend`);
      return "insufficient";
    }
    if (e instanceof AlreadyRenewedError) return "already"; // someone else advanced the period
    throw e;
  }

  // The period is settled. Any 3-D Secure challenge still hanging off it is a
  // loaded gun: anything that later confirms that intent takes a SECOND payment
  // for a period we have already been paid for. Only worth a Stripe round-trip
  // when this server was actually mid-dunning.
  if (server.dunningStage > 0 || server.dunningPayUrl) {
    await cancelPendingChargeForMarker(
      server.user.stripeCustomerId,
      renewalChargeMarker(server.id, periodStart),
    );
  }

  // A settled period ends the reminder cycle: clear the card-less renewal reminder
  // so the NEXT approach-to-expiry can remind once more. Guarded on the in-memory
  // flag so the wallet-only majority skip the write, and best-effort so this
  // housekeeping can never unwind a renewal that already committed.
  if (reminderSentAt(server)) {
    await reminderServer()
      .update({ where: { id: server.id }, data: { renewalReminderSentAt: null } })
      .catch(() => {});
  }

  // Email the renewal INVOICE with its PDF attached. Best-effort and post-commit —
  // the term is already settled, so a mail failure must never unwind a renewal.
  // Fires exactly once per successful renewal because this is the single "renewed"
  // exit of the CAS-guarded commit, reached by BOTH the wallet-only path and the
  // card path. Deliberately `invoiceNew` (subject "Invoice #… — $… due"), NOT
  // `receipt`: a card renewal already gets a distinct card-charge paymentReceipt
  // above, and a second "Payment received — $…" would duplicate it — this is the
  // invoice document instead. `kind:"invoice"` is ACCOUNT-tier (suppressible), and
  // the `invoice_new` template is in the mailer's attach set, so the PDF attaches.
  // Read via the declared union — the value is assigned inside the $transaction
  // callback, which TS control-flow analysis does not track, so a direct read would
  // narrow to `null`.
  const invForEmail = renewedInvoice as { id: string; number: number; amountCents: number } | null;
  // Payment record: the renewal itself (wallet debit; a card top-up leg is
  // recorded separately by chargeSavedCardOffSession). lib/payment-events.ts.
  if (invForEmail) {
    await recordPayment({
      type: "payment.renewal", outcome: "succeeded", provider: "wallet", method: "wallet",
      userId: server.userId, serverId: server.id, amountCents: invForEmail.amountCents,
      reference: invForEmail.id, dedupeKey: `renewal:${server.id}:${periodStart.toISOString()}`,
      label: `Renewed ${server.hostname} from the wallet (${(invForEmail.amountCents / 100).toFixed(2)} USD)`,
      data: { invoiceNumber: invForEmail.number, newExpiry: newExpiry.toISOString() },
    }).catch(() => undefined);
  }
  if (invForEmail) {
    try {
      const branding = await invoiceBranding();
      await mail(
        server.user.email,
        server.userId,
        emails.invoiceNew(
          {
            invoiceNumber: displayInvoiceNumber(invForEmail.number, branding.numberPrefix),
            amount: fmtUsd(invForEmail.amountCents),
            dueDate: fmtDay(new Date()),
            description: `${charge.label} — ${server.hostname}`,
            renewal: await renewalNoticeForInvoice(invForEmail.id),
          },
          true, // the itemised PDF is attached (invoiceId passed below)
        ),
        "invoice",
        invForEmail.id,
      );
    } catch (e) {
      console.error("[billing] renewal invoice email failed", e);
    }
  }
  return "renewed";
}

/**
 * Charge the saved card for the wallet shortfall, then renew.
 *
 * The card NEVER pays the invoice directly. It credits the wallet with exactly
 * what Stripe captured, and `commitRenewal` then debits the FULL renewal from the
 * wallet — identical to how checkout splits a purchase. That ordering is what
 * makes a crash safe in both directions: money captured but not yet applied sits
 * in the customer's wallet as credit (visible, spendable, refundable), and a
 * renewal can never be granted without a matching debit.
 *
 * TWO idempotency guards ride on every attempt:
 *  - `marker` (server + period) — a permanent pre-flight lookup at Stripe for a
 *    live PaymentIntent for this exact period, so a crash between "Stripe captured"
 *    and "we recorded it" replays instead of charging again.
 *  - `idempotencyKey` (server + period + attempt + amount) — Stripe replays an
 *    identical request for 24h, which covers two overlapping sweeps of the SAME
 *    scheduled attempt. The attempt and amount are in the key because a genuine
 *    day-3 retry, or a retry for a different remainder after the wallet moved, is a
 *    deliberately NEW charge; reusing the key there would make Stripe reject it.
 *
 * And the credit itself is guarded by the UNIQUE index on
 * `WalletTransaction.stripePaymentIntentId`, so even a replayed capture credits once.
 *
 * @returns a `CardRenewalOutcome`: `renewed: true` plus what Stripe actually took
 * when the term was extended, or `renewed: false` with the reason (and, for a
 * hard decline, the issuer's own message/code) so a caller other than the
 * automatic sweep — which only ever needed the boolean — can surface exactly
 * what happened instead of a bare failure. See `renewServerImmediately` below,
 * the admin "Renew now" caller this was broadened for (2026-09-25): swallowing
 * `result.message` here would mean adminRenewServerNow could report "declined"
 * but never the reason a decline actually happened, which the admin needs to
 * decide what to tell the customer.
 */
export type CardRenewalOutcome =
  | { renewed: true; amountCents: number; replayed: boolean }
  | {
      renewed: false;
      /** Why no charge landed. `walletDebitRaced` is not a decline at all — see below. */
      kind: "transient" | "unavailable" | "requiresAction" | "declined" | "walletDebitRaced";
      message: string;
      /** Present only for `kind: "declined"` — the issuer's own decline code, when Stripe supplied one. */
      code?: string;
    };

/** Payment-timeline record for a dunning step (lib/payment-events.ts). Never throws. */
async function recordDunning(server: { id: string; userId: string; hostname: string }, step: string, label: string, amountCents?: number | null): Promise<void> {
  await recordPayment({
    type: "payment.dunning", outcome: "failed", provider: "stripe", method: "card",
    userId: server.userId, serverId: server.id, amountCents: amountCents ?? null,
    label: `${server.hostname}: ${label}`, data: { step },
  }).catch(() => undefined);
}

