/**
 * Recurring billing for the add-on products: business email subscriptions and
 * block-storage volumes. Until this existed only the *first* period was charged
 * at order time and nothing ever renewed — every one of these products was
 * silently free after month one.
 *
 * Policy (mirrors worker/billing.ts so the whole account behaves the same):
 *   T-3d   warn the owner if the renewal would fail (no funds / auto-renew off)
 *   T+0    charge the wallet, push `expiresAt` forward one term
 *   T+0..G still unpaid: keep it running, nag once per dedupe window
 *   T+G    enforce — email: status SUSPENDED (mailboxes kept)
 *                    volume: DETACHED + VOLUME_DETACH job (data kept)
 * Nothing here ever deletes customer data.
 *
 * The orchestrator (worker/index.ts) calls `productRenewalSweep()` on a timer.
 * Every step is individually try/caught so one poisoned row can never abort the
 * sweep, and every mutation is a conditional compare-and-swap so a re-run — or
 * two workers racing — can never double-charge.
 */

const LOG = "[product-billing]";

/** Thrown inside a renewal transaction when another sweep already handled the row. */
class AlreadyHandledError extends Error {
  constructor(what: string) {
    super(`already handled: ${what}`);
    this.name = "AlreadyHandledError";
  }
}

/** Run a sweep phase, swallowing (but logging) any failure so the rest proceeds. */
async function phase(name: string, fn: () => Promise<void>): Promise<void> {
  try {
    await fn();
  } catch (e) {
    console.error(`${LOG} phase "${name}" failed`, e);
  }
}

/** Run a per-row step; a bad row is logged and skipped, never fatal. */
async function step(what: string, fn: () => Promise<void>): Promise<void> {
  try {
    await fn();
  } catch (e) {
    console.error(`${LOG} ${what} failed`, e);
  }
}

/** Best-effort notification (a notify failure must never roll back a charge). */
async function notify(userId: string, title: string, body?: string, href?: string) {
  try {
    await db.notification.create({ data: { userId, title, body, href } });
  } catch (e) {
    console.error(`${LOG} notify failed`, e);
  }
}

/**
 * Send a notification at most once per dedupe window, keyed on the entity label
 * plus a stable marker phrase in the title (same technique as worker/billing.ts).
 */
async function notifyOnce(
  now: Date,
  userId: string,
  label: string,
  marker: string,
  title: string,
  body: string,
  href: string
) {
  const already = await db.notification.findFirst({
    where: {
      userId,
      createdAt: { gt: dedupeSince(now) },
      AND: [{ title: { contains: label } }, { title: { contains: marker } }],
    },
    select: { id: true },
  });
  if (already) return;
  await notify(userId, title, body, href);
}

// ---------------------------------------------------------------------------

// ---------------------------------------------------------------------------
// Term-aware renewal pricing (shared by email + hosting)
//
// Both products now carry a per-subscription billing term (1 = monthly, 12 =
// annual) and a frozen annual discount, so a renewal is priced through the SAME
// `termPriceCents` formula the order charged — displayed === charged === renewed.
// The frozen rate WINS; `liveAnnual` (resolved once per sweep) is only the
// fallback for rows that predate the column, and for a monthly term the formula
// collapses to the plain monthly price so no existing row moves.
// ---------------------------------------------------------------------------

/** Per-term renewal price of an email subscription (frozen annual rate wins). */
function emailRenewalPrice(
  sub: { termMonths?: number | null; annualDiscountPct?: number | null; emailPlan: { priceCents: number; termMonths?: number | null } },
  liveAnnual: number,
): number {
  const months = subscriptionTermMonths(sub);
  const annual = frozenProductAnnualPct(sub) ?? liveAnnual;
  return productTermRenewalCents(emailMonthlyBaseCents(sub.emailPlan), months, annual);
}

/**
 * CREATOR PARTNER PROGRAM (2026-09-28): the customer's RECURRING partner
 * discount (10% for a customer attached to an ACTIVE partner, 0 otherwise)
 * applied to a hosting/email renewal — the same `partnerDiscountForRenewal` +
 * `partnerDiscountCentsFor` worker/billing.ts feeds VPS/game renewals through
 * lib/renewal-charge.ts. A renewal is never a first purchase, so this is never
 * the 50% tier. Until this existed, web hosting and business email renewals
 * silently billed an attached customer full price.
 */
type PartnerRenewal = { priceCents: number; partnerDiscountCents: number; partnerDiscountPercent: number };
async function partnerRenewalPrice(userId: string, baseCents: number): Promise<PartnerRenewal> {
  const partnerDiscountPercent = (await partnerDiscountForRenewal(userId)).percent;
  const partnerDiscountCents = partnerDiscountCentsFor(baseCents, partnerDiscountPercent);
  return { priceCents: baseCents - partnerDiscountCents, partnerDiscountCents, partnerDiscountPercent };
}

/** Invoice lines for a renewal: the full-price line, plus the partner discount's
 *  own negative line when there is one (same layout as VPS/game renewals in
 *  worker/billing.ts). Always sums to `r.priceCents`. */
function renewalLineItems(description: string, subject: string, r: PartnerRenewal) {
  const baseCents = r.priceCents + r.partnerDiscountCents;
  return [
    { description, qty: 1, unitCents: baseCents, amountCents: baseCents },
    ...(r.partnerDiscountCents > 0
      ? [
          {
            description: `Partner discount — ${r.partnerDiscountPercent}% off (${subject})`,
            qty: 1,
            unitCents: -r.partnerDiscountCents,
            amountCents: -r.partnerDiscountCents,
          },
        ]
      : []),
  ];
}

