/**
 * SQL fragments shared by the report aggregation layer. The single most
 * important one is REAL_USER: who counts as a customer in a report.
 *
 * Stricter than CUSTOMER_WHERE (lib/insights/common.ts) on purpose: the
 * hand-run signup-friction analysis of 2026-10-06 found 17 internal QA
 * accounts (…@nxeon-internal.test) with role CUSTOMER and excludeFromRevenue
 * false — one of them alone produced 35 of 49 game provision errors in a week.
 * Revenue was unaffected (their orders are $0) but every funnel, provisioning
 * and signup rate was polluted. So reports also drop the internal e-mail
 * suffixes in lib/reports/classify.ts, and the engine raises a data-hygiene
 * finding while any such account is still unflagged.
 */
import { Prisma } from "@prisma/client";
import { INTERNAL_EMAIL_SUFFIXES } from "./classify";
import { NON_REVENUE_PREFIXES } from "@/lib/admin-metrics";

/** `<alias>` is a "User" row that counts as a real customer. */
export function realUser(alias: string): Prisma.Sql {
  if (!/^[a-z_][a-z0-9_]*$/i.test(alias)) throw new Error("bad alias");
  const internal = INTERNAL_EMAIL_SUFFIXES.map((s) => `lower(${alias}.email) LIKE '%${s.replace(/'/g, "")}'`).join(" OR ");
  return Prisma.raw(`(${alias}.role::text = 'CUSTOMER' AND ${alias}."excludeFromRevenue" = false AND NOT (${internal}))`);
}

/** `<alias>` is a "WalletTransaction" row that is earned revenue (a non-reversal debit). */
export function revenueDebit(alias: string): Prisma.Sql {
  if (!/^[a-z_][a-z0-9_]*$/i.test(alias)) throw new Error("bad alias");
  const notRev = NON_REVENUE_PREFIXES.map((p) => `${alias}.description LIKE '${p.replace(/'/g, "")}%'`).join(" OR ");
  return Prisma.raw(`(${alias}."amountCents" < 0 AND NOT (${notRev}))`);
}

/** `<alias>` is a "WalletTransaction" row that is real cash in (card / PayPal / crypto). */
export function realCashIn(alias: string): Prisma.Sql {
  if (!/^[a-z_][a-z0-9_]*$/i.test(alias)) throw new Error("bad alias");
  return Prisma.raw(`(${alias}."amountCents" > 0 AND (${alias}."stripeSessionId" IS NOT NULL OR ${alias}."stripePaymentIntentId" IS NOT NULL))`);
}

