import type { GrantBillingInfo } from "./grant-billing-text";

/** serverId -> live grant policy, for every given server that has a PartnerGrant (one query). */
export async function grantBillingFor(serverIds: string[]): Promise<Map<string, NonNullable<GrantBillingInfo>>> {
  const out = new Map<string, NonNullable<GrantBillingInfo>>();
  if (serverIds.length === 0) return out;
  const rows = await db.partnerGrant.findMany({ where: { serverId: { in: serverIds } }, select: { serverId: true, onExpiry: true, status: true } });
  for (const r of rows) if (r.serverId) out.set(r.serverId, { onExpiry: r.onExpiry, status: r.status });
  return out;
}
/**
 * Customer-facing renewal wording for a server that was GRANTED (PartnerGrant), pure + tested.
 *
 * Bug (2026-10-02): the My Services card said "Renews Nov 2, 2026 $11.50/mo" for a grant set to
 * EXPIRE (auto-renew off, nothing will ever be charged). The truth, by policy:
 *   EXPIRE         "Free until <date>"  — no charge, ever, unless the partner renews it themselves
 *   RENEW_WALLET   "Renews at $X on <date>" — the one policy that really charges
 * Once the grant is CONVERTED (the partner paid for more) or EXPIRED it is an ordinary server again,
 * so no grant wording applies (callers pass null).
 */
export type GrantBillingInfo = { onExpiry: string; status: string } | null | undefined;

/** Statuses during which the grant wording is the truth. REVOKED: auto-renew is off, the server runs out its term free. */
const LIVE = new Set(["ACTIVE", "EXPIRING", "REVOKED"]);

export function isGrantFree(g: GrantBillingInfo): boolean {
  return !!g && LIVE.has(g.status) && !(g.onExpiry === "RENEW_WALLET" && g.status !== "REVOKED");
}

export function isGrantRenewing(g: GrantBillingInfo): boolean {
  return !!g && (g.status === "ACTIVE" || g.status === "EXPIRING") && g.onExpiry === "RENEW_WALLET";
}

function fmtDate(iso: string | Date): string {
  return new Date(iso).toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric", timeZone: "UTC" });
}

