/** StatCard with an automatic "vs previous period" delta. `higherIsBetter` picks the colour. */
export function Kpi({
  label,
  value,
  cur,
  prev,
  higherIsBetter = true,
  note,
  spark,
}: {
  label: string;
  value: string;
  cur?: number | null;
  prev?: number | null;
  higherIsBetter?: boolean;
  note?: string;
  spark?: number[];
}) {
  const ch = cur != null ? relChange(cur, prev) : null;
  const delta = fmtDelta(ch) ?? note;
  const good = ch == null ? undefined : higherIsBetter ? ch >= 0 : ch <= 0;
  return <StatCard label={label} value={value} delta={delta} deltaGood={good} spark={spark} />;
}

