/**
 * Renewal analytics — the PURE half (no DB, no React, no server-only imports),
 * unit-tested in test/renewal-analytics.test.ts. lib/renewal-analytics.ts loads
 * the real rows and hands them here as plain inputs.
 *
 * THE MODEL. Every paid service (VPS, game server, web hosting, business email,
 * domain, block-storage volume) is a chain of billing periods. Each time a
 * period ends the service owes a renewal; one such "renewal cycle" is
 * (service, due date) and gets exactly ONE outcome:
 *
 *   renewed    a renewal was collected for that period (wallet, card, PayPal or
 *              a mix) — sweep, admin "Renew now", or the customer's own renew.
 *              `recovered` marks one that was paid only after a failed charge.
 *   failed     INVOLUNTARY churn: auto-renew was on (the customer meant to keep
 *              it) but the money never arrived — the card declined / was
 *              unusable / the wallet was short, and the service was suspended,
 *              terminated, or removed unpaid.
 *   voluntary  VOLUNTARY churn: the customer chose to leave — auto-renew was off
 *              when the period ended (incl. "cancel at period end"), or they
 *              deleted / cancelled the service themselves (before term end or
 *              after it lapsed without any failed charge).
 *   admin      removed by Nxeon (fraud teardown, abuse/admin-suspension reaping,
 *              admin cleanup). Not a customer decision: excluded from rates.
 *   pending    the period has ended, nothing is collected yet and no outcome is
 *              final (inside the dunning / grace window).
 *   upcoming   the period has not ended yet.
 *
 * WHEN A CYCLE COUNTS. A decided cycle is placed at its `decidedAt` — the
 * EARLIER of its due date and the moment it was settled. An on-time renewal is
 * at its due date, a renewal paid in advance at the day it was paid, a failure
 * at its due date, and a cancellation before term end at the day of the
 * cancellation. So every number in a period is "renewals decided in that
 * period", and nothing ever lands in the future.
 */

export type Product = "vps" | "game" | "hosting" | "email" | "domain" | "volume";
export const PRODUCTS: Product[] = ["vps", "game", "hosting", "email", "domain", "volume"];
export const PRODUCT_LABEL: Record<Product, string> = {
  vps: "VPS",
  game: "Game servers",
  hosting: "Web hosting",
  email: "Business email",
  domain: "Domains",
  volume: "Block storage",
};

/** How a renewal was (or would have been) paid. */
export type Method = "wallet" | "card" | "wallet+card" | "paypal" | "free";
export const METHOD_LABEL: Record<Method, string> = {
  wallet: "Wallet only",
  card: "Card only",
  "wallet+card": "Wallet + card",
  paypal: "PayPal",
  free: "$0 renewal",
};
/** The rail a FAILED cycle failed on. */
export type FailRail = "card" | "wallet" | "paypal";

export type Outcome = "renewed" | "failed" | "voluntary" | "admin" | "pending" | "upcoming";
export const DECIDED: Outcome[] = ["renewed", "failed", "voluntary", "admin"];

/** How a no-longer-existing service ended, from the audit trail. */
export type EndKind = "customer" | "admin" | "unpaid" | "unknown";

export type Funding = "wallet" | "card" | "at_risk";

export type ServiceInput = {
  /** `${product}:${id}` — unique across products. */
  key: string;
  id: string;
  product: Product;
  userId: string;
  label: string;
  startedAt: Date;
  termMonths: number;
  /** Row still exists and is not being torn down. */
  alive: boolean;
  /** Currently suspended (any reason). */
  suspended: boolean;
  /** Current period end (alive rows), or the last KNOWN period end of a removed service. */
  expiresAt: Date | null;
  /** The live row's auto-renew flag (null when the row is gone). */
  autoRenewNow: boolean | null;
  endedAt: Date | null;
  endKind: EndKind | null;
  endNote?: string | null;
  /** What the open / next renewal costs (cents, what the sweep would charge). */
  expectedCents: number | null;
  /** True when `expectedCents` is reconstructed (catalog price of a removed service), not quoted. */
  expectedEstimated?: boolean;
  /** Pre-tax portion of `expectedCents` (servers can carry VAT; other products never do). */
  expectedTaxCents?: number;
  /** Who/what would pay the next renewal right now (alive, auto-renew on). */
  funding?: Funding | null;
};

export type SuccessInput = {
  serviceKey: string;
  at: Date;
  /** The period start the renewal paid for (the old expiry). null = unknown, use `at`. */
  dueAt: Date | null;
  amountCents: number;
  method: Method;
  cardCents: number;
  walletCents: number;
  source: "sweep" | "admin" | "customer";
  invoiceId?: string | null;
};

export type FailureKind = "card_declined" | "card_unusable" | "wallet_short" | "paypal_failed" | "suspended_unpaid" | "terminated_unpaid";
export type FailureInput = {
  serviceKey: string;
  at: Date;
  kind: FailureKind;
  amountCents?: number | null;
  note?: string | null;
};

export type AutoRenewEvent = { serviceKey: string; at: Date; on: boolean };

export type Cycle = {
  serviceKey: string;
  serviceId: string;
  product: Product;
  userId: string;
  label: string;
  /** 1 = the service's first renewal. */
  index: number;
  dueAt: Date;
  /** When it was settled (paid / suspended / cancelled). null when not settled or unknown. */
  resolvedAt: Date | null;
  /** Earlier of due date and settlement — the instant this cycle is counted at. */
  decidedAt: Date;
  outcome: Outcome;
  /** Paid only after at least one failed attempt in the same period. */
  recovered: boolean;
  /** Paid more than a day before it was due. */
  early: boolean;
  /** Collected (renewed) or what it would have cost (others). */
  amountCents: number;
  estimated: boolean;
  method: Method | null;
  failRail: FailRail | null;
  cardCents: number;
  walletCents: number;
  failures: number;
  autoRenewAtDue: boolean | null;
  source: SuccessInput["source"] | null;
  reason: string;
  alive: boolean;
  funding: Funding | null;
};

const DAY = 86_400_000;
const HOUR = 3_600_000;

/** Calendar-month add in UTC (estimation only; the billing engine's own addMonths is authoritative). */
export function addMonthsUtc(from: Date, months: number): Date {
  const d = new Date(from.getTime());
  const day = d.getUTCDate();
  d.setUTCMonth(d.getUTCMonth() + months);
  // Clamp overflow (Jan 31 + 1 month -> last day of Feb), same spirit as the engine.
  if (d.getUTCDate() < day) d.setUTCDate(0);
  return d;
}

/* ------------------------------------------------------------------ *
 * Parsing the audit trail (formats written by worker/billing.ts,
 * worker/product-renewals.ts, lib/actions.ts, lib/actions-server-lifecycle.ts)
 * ------------------------------------------------------------------ */

const CUID = /^c[a-z0-9]{20,32}$/;

/** `billing.renewed` / `billing.suspended_unpaid` detail -> which service it is about. */
export function parseBillingDetail(detail: string | null | undefined): { product: "server" | "hosting" | "email" | "volume"; id: string; amountCents: number | null; newExpiry: string | null } | null {
  const d = String(detail ?? "").trim();
  if (!d) return null;
  const first = d.split(/\s+/)[0];
  if (CUID.test(first.replace(/:$/, ""))) return { product: "server", id: first.replace(/:$/, ""), amountCents: null, newExpiry: null };
  const m = /^(hosting|email|volume)\s+(\S+)(.*)$/.exec(d);
  if (!m) return null;
  const rest = m[3] ?? "";
  const amt = /\$(\d+(?:\.\d{1,2})?)/.exec(rest);
  const exp = /->\s*(\d{4}-\d{2}-\d{2})/.exec(rest);
  return {
    product: m[1] as "hosting" | "email" | "volume",
    id: m[2],
    amountCents: amt ? Math.round(parseFloat(amt[1]) * 100) : null,
    newExpiry: exp ? exp[1] : null,
  };
}

/** `billing.card_declined` detail: "<serverId>: attempt 2 for $15.98 — Your card was declined." */
export function parseDeclineDetail(detail: string | null | undefined): { serverId: string; attempt: number | null; amountCents: number | null; message: string } | null {
  const m = /^(c[a-z0-9]{20,32}):\s*(?:attempt\s+(\d+))?(?:\s*for\s*\$(\d+(?:\.\d{1,2})?))?\s*(?:—|-)?\s*(.*)$/.exec(String(detail ?? "").trim());
  if (!m) return null;
  return { serverId: m[1], attempt: m[2] ? Number(m[2]) : null, amountCents: m[3] ? Math.round(parseFloat(m[3]) * 100) : null, message: (m[4] ?? "").trim() };
}

/**
 * `admin.renew_now` detail. Success: "<id> (<host>) renewed via wallet+card — wallet $6.12 + card $21.37 = $27.49, new expiry …".
 * Failure: "<id> (<host>) FAILED — declined: Your card was declined."
 */
export function parseAdminRenewDetail(detail: string | null | undefined):
  | { serverId: string; ok: true; path: Method; walletCents: number; cardCents: number; totalCents: number }
  | { serverId: string; ok: false; reason: string; message: string }
  | null {
  const d = String(detail ?? "").trim();
  const id = /^(c[a-z0-9]{20,32})\b/.exec(d)?.[1];
  if (!id) return null;
  const ok = /renewed via (wallet\+card|wallet|card)\s*—\s*wallet \$(\d+(?:\.\d+)?)\s*\+\s*card \$(\d+(?:\.\d+)?)\s*=\s*\$(\d+(?:\.\d+)?)/.exec(d);
  if (ok) {
    return {
      serverId: id,
      ok: true,
      path: ok[1] as Method,
      walletCents: Math.round(parseFloat(ok[2]) * 100),
      cardCents: Math.round(parseFloat(ok[3]) * 100),
      totalCents: Math.round(parseFloat(ok[4]) * 100),
    };
  }
  const fail = /FAILED\s*—\s*([A-Za-z]+):\s*(.*)$/.exec(d);
  if (fail) return { serverId: id, ok: false, reason: fail[1], message: fail[2] };
  return null;
}

/** `server.autorenew_toggle` detail "<id> -> false". */
export function parseAutoRenewToggle(detail: string | null | undefined): { serverId: string; on: boolean } | null {
  const m = /^(c[a-z0-9]{20,32})\s*->\s*(true|false)/.exec(String(detail ?? "").trim());
  return m ? { serverId: m[1], on: m[2] === "true" } : null;
}

/** First "(hostname)" in an order/renewal invoice description. */
export function hostnameFromDescription(desc: string | null | undefined): string | null {
  const re = /\(([a-z0-9][a-z0-9.-]{1,62})\)/gi;
  let m: RegExpExecArray | null;
  while ((m = re.exec(String(desc ?? "")))) {
    const h = m[1].toLowerCase();
    // Skip parenthesised things that aren't hostnames ("(COMEBACK50)", "(paypal …)").
    if (/^[a-z0-9-]+(\.[a-z0-9-]+)*$/.test(h) && /[a-z]/.test(h) && !/^(paypal|monthly|annual|comeback\d*)$/.test(h)) return h;
  }
  return null;
}

/** "term=12mo" in an order audit detail. */
export function termFromOrderDetail(detail: string | null | undefined): number {
  const m = /\bterm=(\d+)mo\b/.exec(String(detail ?? ""));
  const n = m ? Number(m[1]) : 1;
  return Number.isFinite(n) && n >= 1 ? n : 1;
}

/* ------------------------------------------------------------------ *
 * Real-customer scoping
 * ------------------------------------------------------------------ */

/**
 * Keep only rows owned by a real customer. `realUserIds` is produced by the
 * report layer's `realUser()` SQL (lib/reports/sql.ts: role CUSTOMER,
 * excludeFromRevenue false, no internal QA e-mail suffix). Anything whose owner
 * is unknown (deleted account) is dropped too — it cannot be verified as real.
 */
export function scopeToRealUsers<T extends { userId: string | null | undefined }>(rows: T[], realUserIds: Set<string>): T[] {
  return rows.filter((r) => !!r.userId && realUserIds.has(r.userId));
}

/* ------------------------------------------------------------------ *
 * Cycle construction + classification
 * ------------------------------------------------------------------ */

export type BuildOpts = {
  now: Date;
  /**
   * Days after the due date during which an unpaid, unsuspended, still-alive
   * service is "pending" rather than failed. Matches the dunning window: cards
   * are retried on days 1/3/5 and suspension lands after the grace days.
   */
  pendingDays?: number;
};

function autoRenewAt(events: AutoRenewEvent[], at: Date, fallback: boolean | null): boolean | null {
  // `events` sorted ascending. State = last event at/before `at`; before the first
  // event the state was the opposite of what the first event switched it to.
  let state: boolean | null = null;
  for (const e of events) {
    if (e.at.getTime() <= at.getTime()) state = e.on;
    else break;
  }
  if (state != null) return state;
  if (events.length) return !events[0].on;
  return fallback;
}

function failRailOf(fs: FailureInput[]): FailRail | null {
  if (fs.some((f) => f.kind === "card_declined" || f.kind === "card_unusable")) return "card";
  if (fs.some((f) => f.kind === "paypal_failed")) return "paypal";
  if (fs.length) return "wallet";
  return null;
}

/** Build every renewal cycle of every service. Pure. */
export function buildCycles(
  services: ServiceInput[],
  successes: SuccessInput[],
  failures: FailureInput[],
  autoRenewEvents: AutoRenewEvent[],
  opts: BuildOpts,
): Cycle[] {
  const now = opts.now;
  const pendingMs = (opts.pendingDays ?? 14) * DAY;
  const byKey = <T extends { serviceKey: string; at: Date }>(rows: T[]) => {
    const m = new Map<string, T[]>();
    for (const r of rows) m.set(r.serviceKey, [...(m.get(r.serviceKey) ?? []), r]);
    for (const v of m.values()) v.sort((a, b) => a.at.getTime() - b.at.getTime());
    return m;
  };
  const succ = byKey(successes);
  const fail = byKey(failures);
  const ar = byKey(autoRenewEvents);
  const out: Cycle[] = [];

  for (const s of services) {
    const ss = succ.get(s.key) ?? [];
    const fs = fail.get(s.key) ?? [];
    const evs = ar.get(s.key) ?? [];
    const base = {
      serviceKey: s.key,
      serviceId: s.id,
      product: s.product,
      userId: s.userId,
      label: s.label,
      alive: s.alive,
    };
    let prevAt = s.startedAt.getTime() - 1;
    let lastDue: Date | null = null;
    let lastAmount: number | null = null;

    ss.forEach((r, i) => {
      const dueAt = r.dueAt ?? r.at;
      const inCycle = fs.filter((f) => f.at.getTime() > prevAt && f.at.getTime() <= r.at.getTime() && f.kind !== "suspended_unpaid" && f.kind !== "terminated_unpaid");
      const suspendedInCycle = fs.some((f) => f.at.getTime() > prevAt && f.at.getTime() <= r.at.getTime() && f.kind === "suspended_unpaid");
      out.push({
        ...base,
        index: i + 1,
        dueAt,
        resolvedAt: r.at,
        decidedAt: new Date(Math.min(dueAt.getTime(), r.at.getTime())),
        outcome: "renewed",
        recovered: inCycle.length > 0 || suspendedInCycle,
        early: r.at.getTime() < dueAt.getTime() - DAY,
        amountCents: r.amountCents,
        estimated: false,
        method: r.method,
        failRail: null,
        cardCents: r.cardCents,
        walletCents: r.walletCents,
        failures: inCycle.length,
        autoRenewAtDue: autoRenewAt(evs, dueAt, s.autoRenewNow),
        source: r.source,
        reason: r.source === "admin" ? "renewed by an admin (Renew now)" : r.source === "customer" ? "renewed by the customer" : "renewed automatically",
        funding: null,
      });
      prevAt = r.at.getTime();
      lastDue = dueAt;
      lastAmount = r.amountCents;
    });

    // ---- The open (current / final) cycle ----
    const index = ss.length + 1;
    const lastDueD = lastDue as Date | null;
    const dueAt: Date | null = s.expiresAt ?? (lastDueD ? addMonthsUtc(lastDueD, s.termMonths) : addMonthsUtc(s.startedAt, s.termMonths));
    if (!dueAt) continue;
    // A removed service whose last renewal already pushed its period past the
    // removal is still one open cycle; a live one too. Failures after the last
    // success belong to it.
    const open = fs.filter((f) => f.at.getTime() > prevAt);
    const attempts = open.filter((f) => f.kind !== "suspended_unpaid" && f.kind !== "terminated_unpaid");
    const suspendedAt = open.find((f) => f.kind === "suspended_unpaid")?.at ?? null;
    const terminatedAt = open.find((f) => f.kind === "terminated_unpaid")?.at ?? null;
    const arAtDue = autoRenewAt(evs, new Date(Math.min(dueAt.getTime(), now.getTime(), s.endedAt?.getTime() ?? Infinity)), s.alive ? s.autoRenewNow : (s.autoRenewNow ?? true));
    const amount = s.expectedCents ?? lastAmount ?? 0;
    const estimated = s.expectedCents == null || !!s.expectedEstimated;

    let outcome: Outcome;
    let resolvedAt: Date | null = null;
    let reason: string;
    if (s.alive) {
      if (dueAt.getTime() > now.getTime()) {
        outcome = "upcoming";
        reason = arAtDue === false ? "auto-renew is off — will not renew unless turned back on" : "renews on its due date";
      } else if (arAtDue === false) {
        outcome = "voluntary";
        resolvedAt = suspendedAt ?? dueAt;
        reason = "auto-renew was off when the period ended";
      } else if (suspendedAt || terminatedAt || (s.suspended && attempts.length)) {
        outcome = "failed";
        resolvedAt = suspendedAt ?? terminatedAt ?? dueAt;
        reason = "unpaid — suspended for non-payment";
      } else if (now.getTime() - dueAt.getTime() > pendingMs) {
        outcome = "failed";
        resolvedAt = null;
        reason = `unpaid more than ${Math.round(pendingMs / DAY)} days after the due date`;
      } else {
        outcome = "pending";
        reason = attempts.length ? `in dunning — ${attempts.length} failed attempt${attempts.length === 1 ? "" : "s"} so far` : "due, not collected yet";
      }
    } else {
      const ended = s.endedAt;
      if (s.endKind === "admin") {
        outcome = "admin";
        resolvedAt = ended;
        reason = s.endNote || "removed by Nxeon";
      } else if (terminatedAt || s.endKind === "unpaid") {
        outcome = "failed";
        resolvedAt = terminatedAt ?? ended;
        reason = "terminated for non-payment";
      } else if (ended && ended.getTime() < dueAt.getTime() - HOUR) {
        // Gone before the period it paid for ran out — a customer cancellation
        // (a failed charge cannot precede the due date except via an early admin
        // attempt, which never ends a service by itself).
        outcome = "voluntary";
        resolvedAt = ended;
        reason = s.endNote || "cancelled before the term ended";
      } else if (attempts.length || suspendedAt) {
        outcome = arAtDue === false ? "voluntary" : "failed";
        resolvedAt = suspendedAt ?? ended ?? dueAt;
        reason = arAtDue === false ? "auto-renew was off; removed after it lapsed" : "payment failed, then removed";
      } else if (!ended && dueAt.getTime() > now.getTime()) {
        outcome = "voluntary";
        resolvedAt = null;
        reason = "removed before the term ended (no removal record)";
      } else {
        outcome = "voluntary";
        resolvedAt = ended;
        reason = arAtDue === false ? "auto-renew was off; lapsed and removed" : s.endNote || "removed by the customer after it lapsed";
      }
    }
    const decidedAt = outcome === "upcoming" || outcome === "pending" ? dueAt : new Date(Math.min(dueAt.getTime(), (resolvedAt ?? dueAt).getTime()));
    out.push({
      ...base,
      index,
      dueAt,
      resolvedAt,
      decidedAt,
      outcome,
      recovered: false,
      early: false,
      amountCents: amount,
      estimated,
      method: null,
      failRail: outcome === "failed" ? failRailOf(attempts) ?? "wallet" : null,
      cardCents: 0,
      walletCents: 0,
      failures: attempts.length,
      autoRenewAtDue: arAtDue,
      source: null,
      reason,
      funding: s.funding ?? null,
    });
  }
  return out;
}

/* ------------------------------------------------------------------ *
 * Ranges + buckets
 * ------------------------------------------------------------------ */

export type RangeKey = "7d" | "30d" | "90d" | "12m";
export const RANGE_KEYS: { key: RangeKey; label: string }[] = [
  { key: "7d", label: "7 days" },
  { key: "30d", label: "30 days" },
  { key: "90d", label: "90 days" },
  { key: "12m", label: "12 months" },
];
export type BucketKind = "week" | "month";
export type Range = { key: RangeKey; from: Date; to: Date; bucket: BucketKind; label: string };

export function parseRange(sp: { range?: string; bucket?: string }, now: Date): Range {
  const key = (RANGE_KEYS.find((r) => r.key === sp.range)?.key ?? "90d") as RangeKey;
  const from =
    key === "12m"
      ? new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - 11, 1))
      : new Date(now.getTime() - (key === "7d" ? 7 : key === "30d" ? 30 : 90) * DAY);
  const bucket: BucketKind = sp.bucket === "week" || sp.bucket === "month" ? sp.bucket : key === "12m" ? "month" : "week";
  return { key, from, to: now, bucket, label: `Last ${RANGE_KEYS.find((r) => r.key === key)!.label}` };
}

/** Monday 00:00 UTC of the week containing `d`. */
export function weekStartUtc(d: Date): Date {
  const x = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()));
  const dow = (x.getUTCDay() + 6) % 7; // Mon=0
  return new Date(x.getTime() - dow * DAY);
}
export function bucketKey(d: Date, kind: BucketKind): string {
  if (kind === "month") return `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, "0")}`;
  return weekStartUtc(d).toISOString().slice(0, 10);
}
/** Every bucket key from `from` to `to`, oldest first. */
export function bucketKeys(from: Date, to: Date, kind: BucketKind): string[] {
  const keys: string[] = [];
  let cur = kind === "month" ? new Date(Date.UTC(from.getUTCFullYear(), from.getUTCMonth(), 1)) : weekStartUtc(from);
  while (cur.getTime() <= to.getTime()) {
    keys.push(bucketKey(cur, kind));
    cur = kind === "month" ? new Date(Date.UTC(cur.getUTCFullYear(), cur.getUTCMonth() + 1, 1)) : new Date(cur.getTime() + 7 * DAY);
  }
  return keys;
}

/* ------------------------------------------------------------------ *
 * Aggregates
 * ------------------------------------------------------------------ */

export type Tally = {
  renewed: number;
  failed: number;
  voluntary: number;
  admin: number;
  pending: number;
  recovered: number;
  early: number;
  collectedCents: number;
  /** Renewal revenue that fell due: collected + failed + voluntary (expected amounts). */
  dueCents: number;
  lostInvoluntaryCents: number;
  lostVoluntaryCents: number;
};
export function emptyTally(): Tally {
  return { renewed: 0, failed: 0, voluntary: 0, admin: 0, pending: 0, recovered: 0, early: 0, collectedCents: 0, dueCents: 0, lostInvoluntaryCents: 0, lostVoluntaryCents: 0 };
}
export function addToTally(t: Tally, c: Cycle): void {
  switch (c.outcome) {
    case "renewed":
      t.renewed++;
      if (c.recovered) t.recovered++;
      if (c.early) t.early++;
      t.collectedCents += c.amountCents;
      t.dueCents += c.amountCents;
      break;
    case "failed":
      t.failed++;
      t.dueCents += c.amountCents;
      t.lostInvoluntaryCents += c.amountCents;
      break;
    case "voluntary":
      t.voluntary++;
      t.dueCents += c.amountCents;
      t.lostVoluntaryCents += c.amountCents;
      break;
    case "admin":
      t.admin++;
      break;
    case "pending":
      t.pending++;
      break;
    default:
      break;
  }
}

/** null when the denominator is 0 — never a fake 0% / 100%. */
export function ratio(n: number, d: number): number | null {
  return d > 0 ? n / d : null;
}
/** Renewal rate: renewed / (renewed + failed + voluntary). Admin removals and pending excluded. */
export function renewalRate(t: Tally): number | null {
  return ratio(t.renewed, t.renewed + t.failed + t.voluntary);
}
/** Payment success rate: renewed / (renewed + failed) — of the renewals the customer wanted, how many we collected. */
export function paymentSuccessRate(t: Tally): number | null {
  return ratio(t.renewed, t.renewed + t.failed);
}
/** Failure rate: failed / (renewed + failed). */
export function failureRate(t: Tally): number | null {
  return ratio(t.failed, t.renewed + t.failed);
}
/** Revenue retained: collected / due. */
export function revenueRetained(t: Tally): number | null {
  return ratio(t.collectedCents, t.dueCents);
}

export function inWindow(c: Cycle, from: Date, to: Date): boolean {
  if (!DECIDED.includes(c.outcome) && c.outcome !== "pending") return false;
  const t = c.decidedAt.getTime();
  return t >= from.getTime() && t < to.getTime();
}

export function tallyWindow(cycles: Cycle[], from: Date, to: Date, filter?: (c: Cycle) => boolean): Tally {
  const t = emptyTally();
  for (const c of cycles) if (inWindow(c, from, to) && (!filter || filter(c))) addToTally(t, c);
  return t;
}

export function tallyByBucket(cycles: Cycle[], range: Range): { keys: string[]; tallies: Tally[] } {
  const keys = bucketKeys(range.from, range.to, range.bucket);
  const idx = new Map(keys.map((k, i) => [k, i]));
  const tallies = keys.map(() => emptyTally());
  for (const c of cycles) {
    if (!inWindow(c, range.from, new Date(range.to.getTime() + 1))) continue;
    const i = idx.get(bucketKey(c.decidedAt, range.bucket));
    if (i != null) addToTally(tallies[i], c);
  }
  return { keys, tallies };
}

export function tallyBy<K extends string>(cycles: Cycle[], from: Date, to: Date, keyOf: (c: Cycle) => K | null): Map<K, Tally> {
  const m = new Map<K, Tally>();
  for (const c of cycles) {
    if (!inWindow(c, from, to)) continue;
    const k = keyOf(c);
    if (k == null) continue;
    if (!m.has(k)) m.set(k, emptyTally());
    addToTally(m.get(k)!, c);
  }
  return m;
}

/** Method a cycle is attributed to: how it was paid, or (failed) the rail it failed on. */
export function methodKey(c: Cycle): string | null {
  if (c.outcome === "renewed") return c.method ?? "wallet";
  if (c.outcome === "failed") return c.failRail === "card" ? "card" : c.failRail === "paypal" ? "paypal" : "wallet";
  return null;
}

/* ------------------------------------------------------------------ *
 * Upcoming
 * ------------------------------------------------------------------ */

export type Upcoming = {
  count: number;
  cents: number;
  taxCents: number;
  autoRenewOff: number;
  autoRenewOffCents: number;
  atRisk: number;
  atRiskCents: number;
  cards: number;
  wallet: number;
};
export function upcomingWithin(cycles: Cycle[], now: Date, days: number): Upcoming {
  const until = now.getTime() + days * DAY;
  const u: Upcoming = { count: 0, cents: 0, taxCents: 0, autoRenewOff: 0, autoRenewOffCents: 0, atRisk: 0, atRiskCents: 0, cards: 0, wallet: 0 };
  for (const c of cycles) {
    if (c.outcome !== "upcoming") continue;
    const t = c.dueAt.getTime();
    if (t <= now.getTime() || t > until) continue;
    if (c.autoRenewAtDue === false) {
      u.autoRenewOff++;
      u.autoRenewOffCents += c.amountCents;
      continue;
    }
    u.count++;
    u.cents += c.amountCents;
    if (c.funding === "at_risk") {
      u.atRisk++;
      u.atRiskCents += c.amountCents;
    } else if (c.funding === "card") u.cards++;
    else u.wallet++;
  }
  return u;
}

/* ------------------------------------------------------------------ *
 * Cohort renewal curves
 * ------------------------------------------------------------------ */

export type CohortRow = {
  month: string;
  services: number;
  /** cols[k-1] = renewal k: survived / eligible (null eligible = nobody has reached it yet). */
  cols: { survived: number; eligible: number }[];
};

/**
 * By start month: of the services whose k-th renewal has been DECIDED, the
 * share that paid it. A service that churned at renewal j counts as "not
 * survived" for every later k whose (estimated) due date has passed. Pending /
 * upcoming renewals and services Nxeon removed (admin) are left out of that k
 * (censored), never counted as churn.
 */
export function cohortCurves(services: ServiceInput[], cycles: Cycle[], now: Date, maxK = 6): CohortRow[] {
  const byService = new Map<string, Cycle[]>();
  for (const c of cycles) byService.set(c.serviceKey, [...(byService.get(c.serviceKey) ?? []), c]);
  const rows = new Map<string, CohortRow>();
  for (const s of services) {
    const month = bucketKey(s.startedAt, "month");
    if (!rows.has(month)) rows.set(month, { month, services: 0, cols: Array.from({ length: maxK }, () => ({ survived: 0, eligible: 0 })) });
    const row = rows.get(month)!;
    row.services++;
    const cs = (byService.get(s.key) ?? []).sort((a, b) => a.index - b.index);
    const churnAt = cs.find((c) => c.outcome === "failed" || c.outcome === "voluntary");
    const censored = cs.find((c) => c.outcome === "admin" || c.outcome === "pending" || c.outcome === "upcoming");
    for (let k = 1; k <= maxK; k++) {
      const c = cs.find((x) => x.index === k);
      if (c) {
        if (c.outcome === "renewed") {
          row.cols[k - 1].eligible++;
          row.cols[k - 1].survived++;
        } else if (c.outcome === "failed" || c.outcome === "voluntary") {
          row.cols[k - 1].eligible++;
        }
        // admin / pending / upcoming: censored at k
        continue;
      }
      if (churnAt && churnAt.index < k && (!censored || censored.index > churnAt.index)) {
        // Already gone; count once its k-th due date would have passed.
        const est = addMonthsUtc(churnAt.dueAt, (k - churnAt.index) * Math.max(1, s.termMonths));
        if (est.getTime() <= now.getTime()) row.cols[k - 1].eligible++;
      }
    }
  }
  return [...rows.values()].sort((a, b) => (a.month < b.month ? 1 : -1));
}

/* ------------------------------------------------------------------ *
 * Card attempts (attempt-level, not cycle-level)
 * ------------------------------------------------------------------ */

export function cardAttemptStats(successes: SuccessInput[], failures: FailureInput[], from: Date, to: Date): { attempts: number; declined: number; unusable: number; succeeded: number; declineRate: number | null } {
  const inR = (d: Date) => d.getTime() >= from.getTime() && d.getTime() < to.getTime();
  const succeeded = successes.filter((s) => inR(s.at) && s.cardCents > 0).length;
  const declined = failures.filter((f) => inR(f.at) && f.kind === "card_declined").length;
  const unusable = failures.filter((f) => inR(f.at) && f.kind === "card_unusable").length;
  const attempts = succeeded + declined + unusable;
  return { attempts, declined, unusable, succeeded, declineRate: ratio(declined + unusable, attempts) };
}

/* ------------------------------------------------------------------ *
 * Drill-down filter
 * ------------------------------------------------------------------ */

export type DrillKind = "renewed" | "failed" | "voluntary" | "admin" | "pending" | "upcoming7" | "upcoming30" | "recovered" | "all";
export const DRILL_KINDS: DrillKind[] = ["renewed", "failed", "voluntary", "admin", "pending", "upcoming7", "upcoming30", "recovered", "all"];

export function drillCycles(
  cycles: Cycle[],
  q: { kind: DrillKind; product?: string | null; method?: string | null; bucket?: string | null },
  range: Range,
  now: Date,
): Cycle[] {
  let rows: Cycle[];
  if (q.kind === "upcoming7" || q.kind === "upcoming30") {
    const until = now.getTime() + (q.kind === "upcoming7" ? 7 : 30) * DAY;
    rows = cycles.filter((c) => c.outcome === "upcoming" && c.dueAt.getTime() > now.getTime() && c.dueAt.getTime() <= until);
    rows.sort((a, b) => a.dueAt.getTime() - b.dueAt.getTime());
  } else {
    const end = new Date(range.to.getTime() + 1);
    rows = cycles.filter((c) => inWindow(c, range.from, end));
    if (q.kind === "recovered") rows = rows.filter((c) => c.outcome === "renewed" && c.recovered);
    else if (q.kind !== "all") rows = rows.filter((c) => c.outcome === q.kind);
    if (q.bucket) rows = rows.filter((c) => bucketKey(c.decidedAt, range.bucket) === q.bucket);
    rows.sort((a, b) => b.decidedAt.getTime() - a.decidedAt.getTime());
  }
  if (q.product) rows = rows.filter((c) => c.product === q.product);
  if (q.method) rows = rows.filter((c) => methodKey(c) === q.method);
  return rows;
}

