import "server-only";
import { Prisma } from "@prisma/client";
import { db } from "@/lib/db";
import { realUser } from "@/lib/reports/sql";
import { renewalCharge } from "@/lib/renewal-charge";
import { currentRenewalPrices } from "@/lib/admin-metrics";
import { resolveCountryTaxRate, sellerCountry, taxRate } from "@/lib/tax";
import { partnerDiscountForRenewal } from "@/lib/partner-pricing";
import { partnerDiscountCentsFor } from "@/lib/partner-discount";
import { annualDiscountPct } from "@/lib/annual-discount";
import { extraDiskPerGbCents } from "@/lib/disk-expand";
import { hasChargeableCard } from "@/lib/stripe-cards";
import { hasChargeablePayPal } from "@/lib/paypal";
import { getSettingBool } from "@/lib/settings";
import { domainTerm, domainTermPriceCents } from "@/lib/billing-terms";
import {
  VOLUME_TERM_MONTHS,
  emailMonthlyBaseCents,
  frozenProductAnnualPct,
  hostingRenewalPrice,
  productTermRenewalCents,
  subscriptionTermMonths,
  volumeRenewalCents,
} from "@/lib/product-billing";
import {
  buildCycles,
  hostnameFromDescription,
  parseAdminRenewDetail,
  parseAutoRenewToggle,
  parseBillingDetail,
  parseDeclineDetail,
  scopeToRealUsers,
  termFromOrderDetail,
  type AutoRenewEvent,
  type Cycle,
  type EndKind,
  type FailureInput,
  type Funding,
  type Method,
  type ServiceInput,
  type SuccessInput,
} from "@/lib/renewal-analytics-core";

/**
 * Renewal analytics — the DB half. Reads the real billing trail and turns it
 * into the plain inputs lib/renewal-analytics-core.ts classifies. READ-ONLY:
 * nothing here writes. Every source, and why it is the source, is documented
 * in docs/DOCUMENTATION.md ("Renewal analytics").
 *
 * Sources of truth (all written by the money paths themselves):
 *  - success, VPS/game:   AuditLog `billing.renewed` (detail = server id; written by
 *                         worker/billing.ts commitRenewal — the sweep, the admin
 *                         "Renew now" and the unpaid auto-recovery all go through it)
 *                         + `server.renew_now` (the customer's own button,
 *                         lib/actions.ts renewNow), each joined to its PAID
 *                         "Renewal: …" invoice for the amount and period start.
 *  - success, hosting / email / volume: AuditLog `billing.renewed` with detail
 *                         "hosting|email|volume <id> … $X -> YYYY-MM-DD"
 *                         (worker/product-renewals.ts), joined to its invoice.
 *  - success, domains:    WalletTransaction "Domain renewal: <name> (…)" debits
 *                         (both the auto-renew sweep and the manual action write one).
 *  - card leg:            the WalletTransaction credit with a Stripe PaymentIntent
 *                         "Card payment for <host> renewal …" written just before
 *                         the commit (the card funds the wallet, the wallet pays).
 *  - failures:            `billing.card_declined`, `billing.card_unusable_grace`,
 *                         `admin.renew_now … FAILED — insufficientFunds`,
 *                         `billing.suspended_unpaid`, `billing.terminated_unpaid`.
 *  - auto-renew history:  `server.autorenew_toggle`, `server.cancel_period_end`.
 *  - removed services:    the order audit (`server.order` / `gameserver.order`,
 *                         `hosting.order`) + its order invoice (hostname, first
 *                         period end), ended by `server.delete`,
 *                         `server.cancel_immediate`, `admin.server.delete`,
 *                         `admin.fraud_teardown`, `billing.reaped_suspended`, …
 */

const S = 1000;
const MIN = 60 * S;

type Inv = {
  id: string;
  userId: string;
  description: string;
  amountCents: number;
  taxCents: number;
  periodStart: Date | null;
  periodEnd: Date | null;
  createdAt: Date;
  renewalCents: number | null;
};
type WTx = { id: string; userId: string; amountCents: number; description: string; createdAt: Date; stripePaymentIntentId: string | null };
type Aud = { id: string; userId: string | null; action: string; detail: string | null; createdAt: Date };

const AUDIT_ACTIONS = [
  "billing.renewed",
  "server.renew_now",
  "admin.renew_now",
  "billing.card_declined",
  "billing.card_unusable_grace",
  "billing.suspended_unpaid",
  "billing.terminated_unpaid",
  "billing.reaped_suspended",
  "server.autorenew_toggle",
  "server.cancel_period_end",
  "server.cancel_immediate",
  "server.delete",
  "admin.server.delete",
  "admin.fraud_teardown",
  "qa.sweep_teardown",
  "gameserver.order",
  "server.order",
  "hosting.order",
  "hosting.cancel",
];

export type RenewalDataset = {
  generatedAt: Date;
  services: ServiceInput[];
  successes: SuccessInput[];
  failures: FailureInput[];
  autoRenewEvents: AutoRenewEvent[];
  cycles: Cycle[];
  users: Map<string, { email: string; name: string | null }>;
  /** serviceKey -> admin link for the service, when it still exists. */
  links: Map<string, string>;
  excluded: { nonRealServices: number; freeOrGranted: number };
  earliestEvidence: Date | null;
};

function nearest<T extends { createdAt: Date }>(rows: T[], at: Date, before: number, after: number, pred: (r: T) => boolean, used?: Set<unknown>): T | null {
  let best: T | null = null;
  let bestD = Infinity;
  for (const r of rows) {
    const d = r.createdAt.getTime() - at.getTime();
    if (d < -before || d > after) continue;
    if (used?.has(r)) continue;
    if (!pred(r)) continue;
    if (Math.abs(d) < bestD) {
      best = r;
      bestD = Math.abs(d);
    }
  }
  return best;
}

function group<T, K>(rows: T[], key: (r: T) => K): Map<K, T[]> {
  const m = new Map<K, T[]>();
  for (const r of rows) {
    const k = key(r);
    const arr = m.get(k);
    if (arr) arr.push(r);
    else m.set(k, [r]);
  }
  return m;
}

function methodOf(totalCents: number, cardCents: number, paypal: boolean): Method {
  if (paypal && cardCents > 0) return "paypal";
  if (cardCents <= 0) return totalCents === 0 ? "free" : "wallet";
  return cardCents >= totalCents ? "card" : "wallet+card";
}

/** Load + classify everything. One pass of bounded queries; the platform's whole billing history fits in memory. */
export async function loadRenewalDataset(now = new Date()): Promise<RenewalDataset> {
  const realRows = await db.$queryRaw<{ id: string; email: string; name: string | null }[]>(
    Prisma.sql`SELECT u.id, u.email, u.name FROM "User" u WHERE ${realUser("u")}`,
  );
  const realIds = new Set(realRows.map((r) => r.id));
  const users = new Map(realRows.map((r) => [r.id, { email: r.email, name: r.name }]));
  const realList = [...realIds];

  const [audits, invoices, wtx, serversRaw, grants, hostingRows, emailRows, domainRows, volumeRows, plans, gamePlans, hostingPlans, prices, seller, fallbackTax, liveAnnual, perGb, paypalOn] = await Promise.all([
    db.auditLog.findMany({ where: { action: { in: AUDIT_ACTIONS } }, select: { id: true, userId: true, action: true, detail: true, createdAt: true }, orderBy: { createdAt: "asc" } }),
    db.invoice.findMany({
      where: { userId: { in: realList } },
      select: { id: true, userId: true, description: true, amountCents: true, taxCents: true, periodStart: true, periodEnd: true, createdAt: true, renewalCents: true },
    }),
    db.walletTransaction.findMany({
      where: {
        userId: { in: realList },
        OR: [
          { amountCents: { gt: 0 }, description: { contains: "renewal", mode: "insensitive" } },
          { amountCents: { lt: 0 }, description: { startsWith: "Domain renewal:" } },
        ],
      },
      select: { id: true, userId: true, amountCents: true, description: true, createdAt: true, stripePaymentIntentId: true },
    }),
    db.server.findMany({ include: { plan: true, gamePlan: true, dedicatedIp: true, user: true } }),
    db.partnerGrant.findMany({ where: { serverId: { not: null } }, select: { serverId: true, status: true } }),
    db.hostingAccount.findMany({ include: { plan: true, user: true } }),
    db.emailSubscription.findMany({ include: { emailPlan: true, user: true } }),
    db.domain.findMany({ include: { user: true } }),
    db.volume.findMany({ include: { user: true } }),
    db.plan.findMany({ select: { slug: true, priceCents: true } }),
    db.gamePlan.findMany({ select: { name: true, priceCents: true } }),
    db.hostingPlan.findMany({ select: { name: true, priceCents: true } }),
    currentRenewalPrices(),
    sellerCountry(),
    taxRate(),
    annualDiscountPct(),
    extraDiskPerGbCents(),
    getSettingBool("renewals_paypal_fallback_enabled", false),
  ]);

  const byAction = group(audits as Aud[], (a) => a.action);
  const A = (k: string) => byAction.get(k) ?? [];
  const invByUser = group(invoices as Inv[], (i) => i.userId);
  const wtxByUser = group(wtx as WTx[], (w) => w.userId);
  const usedInv = new Set<unknown>();
  const usedTx = new Set<unknown>();

  const partnerPct = new Map<string, number>();
  const partnerFor = async (userId: string) => {
    if (!partnerPct.has(userId)) partnerPct.set(userId, (await partnerDiscountForRenewal(userId)).percent);
    return partnerPct.get(userId)!;
  };

  const services: ServiceInput[] = [];
  const links = new Map<string, string>();
  const excluded = { nonRealServices: 0, freeOrGranted: 0 };
  const grantedIds = new Set(grants.filter((g) => g.status !== "CONVERTED").map((g) => g.serverId!));

  const fundingFor = (u: { balanceCents: number; stripeCustomerId: string | null; stripePaymentMethodId: string | null; paypalVaultId?: string | null }, cents: number, cardAllowed: boolean): Funding => {
    if (u.balanceCents >= cents) return "wallet";
    if (cardAllowed && hasChargeableCard(u)) return "card";
    if (cardAllowed && paypalOn && hasChargeablePayPal({ paypalVaultId: u.paypalVaultId ?? null })) return "card";
    return "at_risk";
  };

  // ---- end-of-life events, by server id and by hostname ----
  type End = { at: Date; kind: EndKind; note: string };
  const endById = new Map<string, End>();
  const endByHost = new Map<string, End>();
  const setEnd = (m: Map<string, End>, k: string, e: End) => {
    const cur = m.get(k);
    if (!cur || e.at < cur.at) m.set(k, e);
  };
  for (const a of A("server.delete")) setEnd(endById, (a.detail ?? "").split(/\s/)[0], { at: a.createdAt, kind: "customer", note: "deleted by the customer" });
  for (const a of A("server.cancel_immediate")) {
    const d = a.detail ?? "";
    const adminNote = /admin (cleanup|teardown)/i.test(d);
    setEnd(endById, d.split(/\s/)[0], { at: a.createdAt, kind: adminNote ? "admin" : "customer", note: adminNote ? "admin cleanup" : "cancelled immediately by the customer" });
  }
  for (const a of A("billing.terminated_unpaid")) setEnd(endById, (a.detail ?? "").split(/\s/)[0], { at: a.createdAt, kind: "unpaid", note: "terminated after prolonged non-payment" });
  for (const a of A("billing.reaped_suspended")) setEnd(endById, (a.detail ?? "").split(/\s/)[0], { at: a.createdAt, kind: "admin", note: `reaped while suspended ${/\((\w+)\)/.exec(a.detail ?? "")?.[1] ?? ""}`.trim() });
  for (const a of A("admin.server.delete")) setEnd(endByHost, (a.detail ?? "").split(/\s/)[0].toLowerCase(), { at: a.createdAt, kind: "unknown", note: `admin delete: ${(a.detail ?? "").replace(/^\S+\s*/, "").slice(0, 120)}` });
  for (const a of A("admin.fraud_teardown")) setEnd(endByHost, (a.detail ?? "").split(/\s/)[0].toLowerCase(), { at: a.createdAt, kind: "admin", note: "fraud teardown" });
  for (const a of A("qa.sweep_teardown")) {
    const h = /\b([a-z0-9-]+)\b/.exec(a.detail ?? "")?.[1];
    if (h) setEnd(endByHost, h.toLowerCase(), { at: a.createdAt, kind: "admin", note: "QA teardown" });
  }

  // ---- auto-renew history ----
  const autoRenewEvents: AutoRenewEvent[] = [];
  for (const a of A("server.autorenew_toggle")) {
    const p = parseAutoRenewToggle(a.detail);
    if (p) autoRenewEvents.push({ serviceKey: `server:${p.serverId}`, at: a.createdAt, on: p.on });
  }
  for (const a of A("server.cancel_period_end")) {
    const id = (a.detail ?? "").trim().split(/\s/)[0];
    if (id) autoRenewEvents.push({ serviceKey: `server:${id}`, at: a.createdAt, on: false });
  }

  // ---- live servers ----
  const serverKey = (id: string) => `server:${id}`;
  const hostOfServer = new Map<string, string>();
  const ownerOfServer = new Map<string, string>();
  const liveServerIds = new Set<string>();
  for (const s of serversRaw) {
    liveServerIds.add(s.id);
    hostOfServer.set(s.id, s.hostname.toLowerCase());
    ownerOfServer.set(s.id, s.userId);
    if (!realIds.has(s.userId)) {
      excluded.nonRealServices++;
      continue;
    }
    if (s.isFree || grantedIds.has(s.id)) {
      excluded.freeOrGranted++;
      continue;
    }
    const taxCtx = resolveCountryTaxRate({ country: s.user.billingCountry ?? null, vatId: s.user.vatId ?? null, sellerCountry: seller, fallbackPercent: fallbackTax });
    // EXACTLY the sweep's price: lib/renewal-charge.ts with the owner's VAT and partner rate.
    const charge = renewalCharge(s, { ...prices, taxRatePercent: taxCtx.ratePercent, partnerDiscountPercent: await partnerFor(s.userId) });
    const deleting = s.status === "DELETING";
    const end = endById.get(s.id) ?? endByHost.get(s.hostname.toLowerCase()) ?? null;
    services.push({
      key: serverKey(s.id),
      id: s.id,
      product: s.gamePlanId ? "game" : "vps",
      userId: s.userId,
      label: s.hostname,
      startedAt: s.createdAt,
      termMonths: charge.months,
      alive: !deleting,
      suspended: s.status === "SUSPENDED",
      expiresAt: s.expiresAt,
      autoRenewNow: s.autoRenew,
      endedAt: deleting ? end?.at ?? s.updatedAt : null,
      endKind: deleting ? end?.kind ?? "customer" : null,
      endNote: deleting ? end?.note ?? "being deleted" : null,
      expectedCents: charge.totalCents,
      expectedTaxCents: charge.taxCents,
      funding: s.autoRenew ? fundingFor(s.user, charge.totalCents, true) : null,
    });
    if (!deleting) links.set(serverKey(s.id), `/admin/servers/${s.id}`);
  }

  // ---- removed servers, reconstructed from their order ----
  const planPrice = new Map(plans.map((p) => [p.slug, p.priceCents]));
  const gamePrice = new Map(gamePlans.map((g) => [g.name, g.priceCents]));
  for (const a of [...A("server.order"), ...A("gameserver.order")]) {
    const d = a.detail ?? "";
    const id = d.split(/\s/)[0];
    if (!id || liveServerIds.has(id) || !a.userId) continue;
    if (!realIds.has(a.userId)) {
      excluded.nonRealServices++;
      continue;
    }
    if (/\bfree=true\b/.test(d)) {
      excluded.freeOrGranted++;
      continue;
    }
    const inv = nearest(invByUser.get(a.userId) ?? [], a.createdAt, 30 * S, 30 * S, (i) => !/renewal/i.test(i.description), usedInv);
    if (inv) usedInv.add(inv);
    const host = hostnameFromDescription(inv?.description) ?? null;
    if (host) hostOfServer.set(id, host);
    ownerOfServer.set(id, a.userId);
    const term = termFromOrderDetail(d);
    const catalog =
      a.action === "server.order"
        ? planPrice.get(/\bplan=([a-z0-9-]+)/.exec(d)?.[1] ?? "") ?? null
        : gamePrice.get((/\btier=(.+?)\s+term=/.exec(d)?.[1] ?? "").trim()) ?? null;
    const end = endById.get(id) ?? (host ? endByHost.get(host) : undefined) ?? null;
    services.push({
      key: serverKey(id),
      id,
      product: a.action === "gameserver.order" ? "game" : "vps",
      userId: a.userId,
      label: host ?? id,
      startedAt: a.createdAt,
      termMonths: term,
      alive: false,
      suspended: false,
      expiresAt: inv?.periodEnd ?? null,
      autoRenewNow: null,
      endedAt: end?.at ?? null,
      endKind: end?.kind ?? "unknown",
      endNote: end?.note ?? "no removal record found",
      expectedCents: inv?.renewalCents ?? (catalog != null ? catalog * (a.action === "server.order" ? term : 1) : inv?.amountCents ?? null),
      expectedEstimated: true,
    });
  }

  // ---- successes + failures for servers ----
  const successes: SuccessInput[] = [];
  const failures: FailureInput[] = [];
  const knownServer = new Set(services.filter((s) => s.key.startsWith("server:")).map((s) => s.id));
  const adminOk = A("admin.renew_now").map((a) => ({ a, p: parseAdminRenewDetail(a.detail) }));

  const serverSuccess = (serverId: string, at: Date, source: SuccessInput["source"]) => {
    if (!knownServer.has(serverId)) return;
    const owner = ownerOfServer.get(serverId)!;
    const host = hostOfServer.get(serverId);
    const inv = nearest(invByUser.get(owner) ?? [], at, 20 * S, 5 * S, (i) => i.description.startsWith("Renewal:") && (!host || i.description.toLowerCase().includes(`(${host})`)), usedInv);
    if (inv) usedInv.add(inv);
    let src = source;
    const adm = adminOk.find((x) => x.p?.ok && x.p.serverId === serverId && x.a.createdAt.getTime() - at.getTime() >= -2 * S && x.a.createdAt.getTime() - at.getTime() <= 15 * S);
    if (adm) src = "admin";
    const total = inv?.amountCents ?? (adm?.p?.ok ? adm.p.totalCents : 0);
    const credit = nearest(
      wtxByUser.get(owner) ?? [],
      at,
      30 * MIN,
      2 * S,
      (w) => w.amountCents > 0 && /^(Card|PayPal) payment for /.test(w.description) && (!host || w.description.toLowerCase().includes(` ${host} `)),
      usedTx,
    );
    if (credit) usedTx.add(credit);
    let cardCents = credit ? Math.min(credit.amountCents, total) : 0;
    if (adm?.p?.ok) cardCents = Math.min(adm.p.cardCents, total);
    const paypal = !!credit && credit.description.startsWith("PayPal");
    successes.push({
      serviceKey: serverKey(serverId),
      at,
      dueAt: inv?.periodStart ?? null,
      amountCents: total,
      cardCents,
      walletCents: Math.max(0, total - cardCents),
      method: methodOf(total, cardCents, paypal),
      source: src,
      invoiceId: inv?.id ?? null,
    });
  };

  for (const a of A("billing.renewed")) {
    const p = parseBillingDetail(a.detail);
    if (p?.product === "server") serverSuccess(p.id, a.createdAt, "sweep");
  }
  for (const a of A("server.renew_now")) {
    const id = (a.detail ?? "").trim().split(/\s/)[0];
    if (id) serverSuccess(id, a.createdAt, "customer");
  }
  for (const a of A("billing.card_declined")) {
    const p = parseDeclineDetail(a.detail);
    if (p && knownServer.has(p.serverId)) failures.push({ serviceKey: serverKey(p.serverId), at: a.createdAt, kind: "card_declined", amountCents: p.amountCents, note: p.message });
  }
  for (const a of A("billing.card_unusable_grace")) {
    const id = /^(c[a-z0-9]{20,32})/.exec(a.detail ?? "")?.[1];
    if (id && knownServer.has(id)) failures.push({ serviceKey: serverKey(id), at: a.createdAt, kind: "card_unusable", note: (a.detail ?? "").replace(/^\S+\s*/, "").slice(0, 160) });
  }
  for (const { a, p } of adminOk) {
    if (p && !p.ok && p.reason === "insufficientFunds" && knownServer.has(p.serverId)) failures.push({ serviceKey: serverKey(p.serverId), at: a.createdAt, kind: "wallet_short", note: p.message });
  }
  for (const a of A("billing.terminated_unpaid")) {
    const id = (a.detail ?? "").split(/\s/)[0];
    if (knownServer.has(id)) failures.push({ serviceKey: serverKey(id), at: a.createdAt, kind: "terminated_unpaid" });
  }

  // ---- hosting ----
  const liveHostDomains = new Set<string>();
  for (const h of hostingRows) {
    liveHostDomains.add(`${h.userId}|${h.primaryDomain.toLowerCase()}`);
    if (!realIds.has(h.userId)) {
      excluded.nonRealServices++;
      continue;
    }
    if (h.status === "PENDING" || h.status === "PROVISIONING" || h.status === "FAILED") continue; // never billed
    const base = hostingRenewalPrice(h, liveAnnual, perGb);
    const cents = base - partnerDiscountCentsFor(base, await partnerFor(h.userId));
    const key = `hosting:${h.id}`;
    const alive = h.status !== "DELETING";
    services.push({
      key,
      id: h.id,
      product: "hosting",
      userId: h.userId,
      label: h.primaryDomain,
      startedAt: h.createdAt,
      termMonths: subscriptionTermMonths(h),
      alive,
      suspended: h.status === "SUSPENDED",
      expiresAt: h.expiresAt,
      autoRenewNow: true, // the hosting sweep always renews (worker/product-renewals.ts passes autoRenew: true)
      endedAt: alive ? null : h.updatedAt,
      endKind: alive ? null : "customer",
      endNote: alive ? null : "cancelled",
      expectedCents: cents,
      funding: fundingFor(h.user, cents, true),
    });
    if (alive) links.set(key, `/admin/hosting`);
  }
  const hostingPlanPrice = new Map(hostingPlans.map((p) => [p.name.toLowerCase(), p.priceCents]));
  const cancels = A("hosting.cancel").slice();
  for (const a of A("hosting.order")) {
    if (!a.userId) continue;
    const [planName, domain] = (a.detail ?? "").split(" · ").map((x) => x.trim());
    if (!domain || liveHostDomains.has(`${a.userId}|${domain.toLowerCase()}`)) continue;
    if (!realIds.has(a.userId)) {
      excluded.nonRealServices++;
      continue;
    }
    const inv = nearest(invByUser.get(a.userId) ?? [], a.createdAt, 30 * S, 30 * S, (i) => /^Web Hosting/.test(i.description) && !/renewal/i.test(i.description), usedInv);
    if (inv) usedInv.add(inv);
    const ci = cancels.findIndex((c) => c.userId === a.userId && c.createdAt > a.createdAt);
    const cancel = ci >= 0 ? cancels.splice(ci, 1)[0] : null;
    services.push({
      key: `hosting:order-${a.id}`,
      id: `order-${a.id}`,
      product: "hosting",
      userId: a.userId,
      label: domain,
      startedAt: a.createdAt,
      termMonths: 1,
      alive: false,
      suspended: false,
      expiresAt: inv?.periodEnd ?? null,
      autoRenewNow: null,
      endedAt: cancel?.createdAt ?? null,
      endKind: cancel ? "customer" : "unknown",
      endNote: cancel ? "cancelled by the customer" : "no longer exists (no removal record)",
      expectedCents: hostingPlanPrice.get((planName ?? "").toLowerCase()) ?? inv?.amountCents ?? null,
      expectedEstimated: true,
    });
  }

  // ---- email ----
  for (const e of emailRows) {
    if (!realIds.has(e.userId)) {
      excluded.nonRealServices++;
      continue;
    }
    const months = subscriptionTermMonths(e);
    const base = productTermRenewalCents(emailMonthlyBaseCents(e.emailPlan), months, frozenProductAnnualPct(e) ?? liveAnnual);
    const cents = base - partnerDiscountCentsFor(base, await partnerFor(e.userId));
    const alive = e.status !== "CANCELLED";
    services.push({
      key: `email:${e.id}`,
      id: e.id,
      product: "email",
      userId: e.userId,
      label: e.domainName,
      startedAt: e.createdAt,
      termMonths: months,
      alive,
      suspended: e.status === "SUSPENDED",
      expiresAt: e.expiresAt,
      autoRenewNow: e.autoRenew,
      endedAt: null,
      endKind: alive ? null : "customer",
      endNote: alive ? null : "cancelled",
      expectedCents: cents,
      funding: e.autoRenew ? fundingFor(e.user, cents, false) : null, // the email sweep is wallet-only
    });
  }

  // ---- domains ----
  for (const d of domainRows) {
    if (!realIds.has(d.userId)) {
      excluded.nonRealServices++;
      continue;
    }
    if (d.status !== "ACTIVE" && d.status !== "EXPIRED") continue;
    const t = domainTerm(d.termYears);
    const cents = domainTermPriceCents(d.renewPriceCents ?? d.priceCents, t.years);
    services.push({
      key: `domain:${d.id}`,
      id: d.id,
      product: "domain",
      userId: d.userId,
      label: d.name,
      startedAt: d.registeredAt ?? d.createdAt,
      termMonths: t.years * 12,
      alive: d.status === "ACTIVE",
      suspended: false,
      expiresAt: d.expiresAt,
      autoRenewNow: d.autoRenew,
      endedAt: null,
      endKind: d.status === "ACTIVE" ? null : "customer",
      endNote: d.status === "ACTIVE" ? null : "expired",
      expectedCents: cents,
      funding: d.autoRenew ? fundingFor(d.user, cents, false) : null,
    });
  }

  // ---- volumes ----
  for (const v of volumeRows) {
    if (!realIds.has(v.userId)) {
      excluded.nonRealServices++;
      continue;
    }
    const cents = volumeRenewalCents(v);
    const alive = v.status !== "DELETING";
    services.push({
      key: `volume:${v.id}`,
      id: v.id,
      product: "volume",
      userId: v.userId,
      label: v.name,
      startedAt: v.createdAt,
      termMonths: VOLUME_TERM_MONTHS,
      alive,
      suspended: false,
      expiresAt: v.expiresAt,
      autoRenewNow: true,
      endedAt: null,
      endKind: alive ? null : "customer",
      expectedCents: cents,
      funding: fundingFor(v.user, cents, false),
    });
  }

  // ---- product successes / failures (hosting, email, volume) ----
  const known = new Set(services.map((s) => s.key));
  const productInvPrefix: Record<string, RegExp> = { hosting: /^Web Hosting renewal:/, email: /^Business Email renewal:/, volume: /^Block storage renewal:/ };
  for (const a of A("billing.renewed")) {
    const p = parseBillingDetail(a.detail);
    if (!p || p.product === "server" || !a.userId) continue;
    const key = `${p.product}:${p.id}`;
    if (!known.has(key)) continue;
    const svc = services.find((s) => s.key === key)!;
    const inv = nearest(invByUser.get(a.userId) ?? [], a.createdAt, 20 * S, 5 * S, (i) => productInvPrefix[p.product].test(i.description) && i.description.toLowerCase().includes(svc.label.toLowerCase()), usedInv);
    if (inv) usedInv.add(inv);
    const total = inv?.amountCents ?? p.amountCents ?? 0;
    const credit =
      p.product === "hosting"
        ? nearest(wtxByUser.get(a.userId) ?? [], a.createdAt, 30 * MIN, 2 * S, (w) => w.amountCents > 0 && w.description.toLowerCase().startsWith(`card payment for ${svc.label.toLowerCase()} hosting renewal`), usedTx)
        : null;
    if (credit) usedTx.add(credit);
    const cardCents = credit ? Math.min(credit.amountCents, total) : 0;
    successes.push({
      serviceKey: key,
      at: a.createdAt,
      dueAt: inv?.periodStart ?? null,
      amountCents: total,
      cardCents,
      walletCents: Math.max(0, total - cardCents),
      method: methodOf(total, cardCents, false),
      source: "sweep",
      invoiceId: inv?.id ?? null,
    });
  }
  for (const a of A("billing.suspended_unpaid")) {
    const p = parseBillingDetail(a.detail);
    if (!p) continue;
    const key = p.product === "server" ? serverKey(p.id) : `${p.product}:${p.id}`;
    if (known.has(key)) failures.push({ serviceKey: key, at: a.createdAt, kind: "suspended_unpaid" });
  }
  // ---- domain successes (wallet debits) ----
  const domainByName = new Map(services.filter((s) => s.product === "domain").map((s) => [s.label.toLowerCase(), s]));
  for (const w of wtx as WTx[]) {
    if (w.amountCents >= 0 || !w.description.startsWith("Domain renewal:")) continue;
    const name = /^Domain renewal:\s*(\S+)/.exec(w.description)?.[1]?.toLowerCase();
    const svc = name ? domainByName.get(name) : undefined;
    if (!svc) continue;
    successes.push({ serviceKey: svc.key, at: w.createdAt, dueAt: null, amountCents: -w.amountCents, cardCents: 0, walletCents: -w.amountCents, method: "wallet", source: "sweep" });
  }

  const scoped = scopeToRealUsers(services, realIds);
  const cycles = buildCycles(scoped, successes, failures, autoRenewEvents, { now });
  const earliest = [...successes.map((s) => s.at), ...failures.map((f) => f.at)].sort((a, b) => a.getTime() - b.getTime())[0] ?? null;
  return { generatedAt: now, services: scoped, successes, failures, autoRenewEvents, cycles, users, links, excluded, earliestEvidence: earliest };
}

