import Link from "next/link";
import { Sparkline } from "./charts";

export function PageHeader({
  title,
  sub,
  children,
}: {
  title: React.ReactNode;
  sub?: string;
  children?: React.ReactNode;
}) {
  return (
    <div className="mb-6 flex flex-wrap items-end justify-between gap-4">
      <div>
        <h1 className="page-title">{title}</h1>
        {sub && <p className="mt-1 text-sm text-slate-400">{sub}</p>}
      </div>
      {children && <div className="flex items-center gap-2">{children}</div>}
    </div>
  );
}

export function StatCard({
  label,
  value,
  delta,
  deltaGood,
  spark,
  sparkColor = "#8a70fb",
  icon,
  href,
}: {
  label: string;
  value: string;
  delta?: string;
  deltaGood?: boolean;
  spark?: number[];
  sparkColor?: string;
  icon?: React.ReactNode;
  href?: string;
}) {
  const inner = (
    <div className="card card-hover flex h-full flex-col justify-between p-5">
      <div className="flex items-start justify-between">
        <div>
          <p className="text-[13px] text-slate-400">{label}</p>
          <p className="mt-1.5 text-2xl font-bold tracking-tight">{value}</p>
          {delta && (
            <p className={`mt-1 text-xs font-medium ${deltaGood === false ? "text-red-400" : "text-emerald-400"}`}>
              {delta}
            </p>
          )}
        </div>
        {icon && (
          <div className="rounded-xl border border-white/[0.08] bg-gradient-to-br from-accent-blue/20 to-brand-500/20 p-2.5 text-brand-300">
            {icon}
          </div>
        )}
      </div>
      {spark && spark.length > 1 && (
        <div className="mt-3">
          <Sparkline data={spark} width={200} height={32} stroke={sparkColor} id={label.replace(/\W/g, "")} />
        </div>
      )}
    </div>
  );
  return href ? <Link href={href}>{inner}</Link> : inner;
}

const statusColors: Record<string, { dot: string; text: string; pulse?: boolean }> = {
  RUNNING: { dot: "bg-emerald-400", text: "text-emerald-400", pulse: true },
  online: { dot: "bg-emerald-400", text: "text-emerald-400", pulse: true },
  STOPPED: { dot: "bg-slate-500", text: "text-slate-400" },
  PENDING: { dot: "bg-amber-400", text: "text-amber-400" },
  PROVISIONING: { dot: "bg-amber-400", text: "text-amber-400", pulse: true },
  REINSTALLING: { dot: "bg-amber-400", text: "text-amber-400", pulse: true },
  DELETING: { dot: "bg-red-400", text: "text-red-400", pulse: true },
  SUSPENDED: { dot: "bg-red-400", text: "text-red-400" },
  ERROR: { dot: "bg-red-400", text: "text-red-400" },
  QUEUED: { dot: "bg-amber-400", text: "text-amber-400" },
  DONE: { dot: "bg-emerald-400", text: "text-emerald-400" },
  // A migration that ran every step but left a source domain dark or a migrated
  // service crash-looping. Amber on purpose: with no entry here it falls back to
  // STOPPED's neutral grey and reads as "nothing to see" — the exact false
  // reassurance this status exists to prevent.
  COMPLETED_WITH_ISSUES: { dot: "bg-amber-400", text: "text-amber-400" },
  FAILED: { dot: "bg-red-400", text: "text-red-400" },
  OPEN: { dot: "bg-amber-400", text: "text-amber-400" },
  ANSWERED: { dot: "bg-brand-300", text: "text-brand-300" },
  CUSTOMER_REPLY: { dot: "bg-amber-400", text: "text-amber-400" },
  CLOSED: { dot: "bg-slate-500", text: "text-slate-400" },
  // Block storage volumes (Volume.status) + business email (EmailSubscription.status).
  // PENDING / SUSPENDED / DELETING are already covered above and behave the same here.
  ACTIVE: { dot: "bg-emerald-400", text: "text-emerald-400", pulse: true },
  ATTACHED: { dot: "bg-emerald-400", text: "text-emerald-400" },
  DETACHED: { dot: "bg-slate-500", text: "text-slate-400" },
  CANCELLED: { dot: "bg-slate-500", text: "text-slate-400" },
};

    </svg>
  );
}

export function AreaChart({
  series,
  width = 720,
  height = 220,
  id,
  yLabel,
  xLabels = [],
  maxY,
}: {
  series: { name: string; data: number[]; color: string }[];
  width?: number;
  height?: number;
  id: string;
  yLabel?: (v: number) => string;
  xLabels?: string[];
  maxY?: number;
}) {
  const all = series.flatMap((s) => s.data);
  if (all.length === 0) return <p className="text-sm text-slate-500">No data yet.</p>;
  const max = maxY ?? Math.max(...all, 1e-9);
  const padL = 46;
  const padB = 22;
}

/** Horizontal ranked bars (label · bar · value). */
export function Bars({ rows, format = (n) => n.toLocaleString("en-US"), color = "#8a70fb", empty = "Nothing in this range." }: { rows: { label: string; value: number; hint?: string }[]; format?: (n: number) => string; color?: string; empty?: string }) {
  if (!rows.length) return <p className="py-6 text-center text-sm text-slate-500">{empty}</p>;
  const max = Math.max(...rows.map((r) => r.value), 1);
  return (
    <div className="space-y-2.5">
      {rows.map((r) => (
        <div key={r.label}>
          <div className="mb-1 flex items-baseline justify-between gap-3 text-sm">
            <span className="min-w-0 truncate" title={r.label}>
              {r.label}
            </span>
            <span className="shrink-0 tabular-nums">
              <span className="font-semibold">{format(r.value)}</span>
              {r.hint && <span className="ml-2 text-xs text-slate-500">{r.hint}</span>}
            </span>
          </div>
          <MeterBar value={r.value} max={max} color={color} />
        </div>
      ))}
    </div>
  );
}

/** Responsive table: horizontal scroll inside the card on narrow screens. */
export function Table({ head, rows, empty = "Nothing in this range." }: { head: string[]; rows: React.ReactNode[][]; empty?: string }) {
  if (!rows.length) return <p className="py-6 text-center text-sm text-slate-500">{empty}</p>;
  return (
    <div className="-mx-5 overflow-x-auto px-5">
      <table className="table-shell min-w-full text-sm">
        <thead>
          <tr>
            {head.map((h) => (
              <th key={h} className="whitespace-nowrap">
                {h}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map((r, i) => (
            <tr key={i}>
              {r.map((c, j) => (
                <td key={j} className={j === 0 ? "max-w-[260px] truncate" : "whitespace-nowrap tabular-nums"}>
                  {c}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export function Grid({ children, cols = 4 }: { children: React.ReactNode; cols?: 2 | 3 | 4 }) {
  const c = cols === 2 ? "sm:grid-cols-2" : cols === 3 ? "sm:grid-cols-2 xl:grid-cols-3" : "grid-cols-2 xl:grid-cols-4";
  return <div className={`grid gap-4 ${cols === 4 ? c : `grid-cols-1 ${c}`}`}>{children}</div>;
}

export function shortKey(k: string): string {
  // "2026-09-14" → "Sep 14", "2026-09" → "Sep 2026"
  if (/^\d{4}-\d{2}-\d{2}$/.test(k)) {
    const d = new Date(`${k}T00:00:00Z`);
    return d.toLocaleDateString("en-US", { month: "short", day: "numeric", timeZone: "UTC" });
  }
  if (/^\d{4}-\d{2}$/.test(k)) {
    const d = new Date(`${k}-01T00:00:00Z`);
    return d.toLocaleDateString("en-US", { month: "short", year: "numeric", timeZone: "UTC" });
  }
  return k;
}

/** Thin x-axis labels: at most ~7 evenly spaced, the rest blank. */
export function axisLabels(keys: string[], max = 7): string[] {
  if (keys.length <= max) return keys.map(shortKey);
  const step = Math.ceil(keys.length / max);
  return keys.map((k, i) => (i % step === 0 || i === keys.length - 1 ? shortKey(k) : ""));
}

