  tallyByBucket,
  tallyWindow,
  upcomingWithin,
  type Cycle,
  type DrillKind,
  type Method,
  type Outcome,
  type Product,
  type Tally,
} from "@/lib/renewal-analytics-core";

export const dynamic = "force-dynamic";

/**
 * /admin/analytics/renewals — renewal + renewal-rate analytics from the real
 * billing trail (see lib/renewal-analytics.ts for every source and
 * docs/DOCUMENTATION.md "Renewal analytics" for every definition). Read-only.
 * Real customers only: the reports' `realUser()` scope (role CUSTOMER,
 * excludeFromRevenue false, no internal QA e-mail suffix).
 */

type SP = { range?: string; bucket?: string; drill?: string; product?: string; method?: string; b?: string };

const pct = (x: number | null) => (x == null ? "—" : `${(x * 100).toFixed(x > 0 && x < 0.1 ? 1 : 0)}%`);
const OUTCOME_LABEL: Record<Outcome, string> = {
  renewed: "Renewed",
  failed: "Failed (involuntary)",
  voluntary: "Churned (voluntary)",
  admin: "Removed by Nxeon",
  pending: "Pending",
  upcoming: "Upcoming",
};
const OUTCOME_TONE: Record<Outcome, string> = {
  renewed: "text-emerald-400",
  failed: "text-red-400",
  voluntary: "text-amber-400",
  admin: "text-slate-400",
  pending: "text-sky-300",
  upcoming: "text-slate-300",
};
const DRILL_LABEL: Record<DrillKind, string> = {
  renewed: "Renewed",
  failed: "Failed (involuntary churn)",
  voluntary: "Voluntary churn",
  admin: "Removed by Nxeon",
  pending: "Pending (in dunning / grace)",
  upcoming7: "Upcoming — next 7 days",
  upcoming30: "Upcoming — next 30 days",
  recovered: "Recovered after a failed charge",
  all: "Every decided renewal",
};

function fmtDay(d: Date | null): string {
  return d ? d.toISOString().slice(0, 10) : "—";
}

export default async function RenewalAnalyticsPage({ searchParams }: { searchParams: Promise<SP> }) {
  await requireArea("analytics");
  const sp = await searchParams;
  const now = new Date();
  const range = parseRange(sp, now);
  const data = await loadRenewalDataset(now);
  const { cycles } = data;
  const end = new Date(now.getTime() + 1);

  const qs = (over: Partial<SP>) => {
    const p = new URLSearchParams();
    const merged: SP = { range: range.key, bucket: range.bucket, ...over };
    for (const [k, v] of Object.entries(merged)) if (v) p.set(k, String(v));
    return `/admin/analytics/renewals?${p.toString()}`;
  };
  const drillHref = (drill: DrillKind, extra: Partial<SP> = {}) => `${qs({ drill, ...extra })}#drill`;

  const up7 = upcomingWithin(cycles, now, 7);
  const up30 = upcomingWithin(cycles, now, 30);
  const t = tallyWindow(cycles, range.from, end);
  const t30 = tallyWindow(cycles, new Date(now.getTime() - 30 * 86_400_000), end);
  const t90 = tallyWindow(cycles, new Date(now.getTime() - 90 * 86_400_000), end);
  const buckets = tallyByBucket(cycles, range);
  const byProduct = tallyBy<Product>(cycles, range.from, end, (c) => c.product);
  const byMethod = tallyBy<string>(cycles, range.from, end, methodKey);
  const card = cardAttemptStats(data.successes, data.failures, range.from, end);
  const cohorts = cohortCurves(data.services, cycles, now, 6);
  const maxK = Math.max(1, ...cohorts.map((r) => r.cols.reduce((m, c, i) => (c.eligible > 0 ? i + 1 : m), 0)));

  const drill = (DRILL_KINDS.includes(sp.drill as DrillKind) ? sp.drill : "upcoming30") as DrillKind;
  const drillRows = drillCycles(cycles, { kind: drill, product: sp.product || null, method: sp.method || null, bucket: sp.b || null }, range, now);

  const churnReasons = (o: "failed" | "voluntary" | "admin") => {
    const m = new Map<string, number>();
    for (const c of cycles) if (c.outcome === o && c.decidedAt >= range.from && c.decidedAt < end) m.set(c.reason, (m.get(c.reason) ?? 0) + 1);
    return [...m.entries()].sort((a, b) => b[1] - a[1]);
  };

  const sinceText = data.earliestEvidence ? `Renewal evidence starts ${fmtDay(data.earliestEvidence)}.` : "No renewal has been recorded yet.";
  const numLink = (n: number, href: string) => (n > 0 ? <Link className="text-brand-300 hover:text-brand-200" href={href}>{n}</Link> : <span className="text-slate-500">0</span>);
  const rateRow = (label: React.ReactNode, x: Tally, extra: Partial<SP> = {}, trailing: React.ReactNode[] = []) => [
    label,
    numLink(x.renewed, drillHref("renewed", extra)),
    numLink(x.failed, drillHref("failed", extra)),
    numLink(x.voluntary, drillHref("voluntary", extra)),
    numLink(x.admin, drillHref("admin", extra)),
    numLink(x.pending, drillHref("pending", extra)),
    pct(renewalRate(x)),
    pct(paymentSuccessRate(x)),
    fmtMoney(x.collectedCents),
    fmtMoney(x.dueCents),
    pct(revenueRetained(x)),
    ...trailing,
  ];
  const rateHead = ["", "Renewed", "Failed", "Voluntary", "Removed", "Pending", "Renewal rate", "Payment success", "Collected", "Due", "Retained"];

  return (
    <div className="space-y-6">
      <PageHeader title="Renewals" sub={`${range.label} · real customers only · ${sinceText}`}>
        <Link href="/admin/analytics" className="btn-ghost text-sm">
          ← Business analytics
        </Link>
      </PageHeader>

      <div className="flex flex-wrap items-center gap-2 text-sm">
        <span className="text-xs uppercase tracking-wide text-slate-500">Range</span>
        {RANGE_KEYS.map((r) => (
          <Link
            key={r.key}
            href={qs({ range: r.key, bucket: undefined, drill: sp.drill, product: sp.product, method: sp.method })}
            className={`rounded-lg px-3 py-1.5 ${r.key === range.key ? "bg-brand-500/20 font-medium text-brand-200" : "text-slate-400 hover:bg-white/[0.04]"}`}
          >
            {r.label}
          </Link>
        ))}
        <span className="ml-3 text-xs uppercase tracking-wide text-slate-500">Buckets</span>
        {(["week", "month"] as const).map((b) => (
          <Link
            key={b}
            href={qs({ bucket: b, drill: sp.drill, product: sp.product, method: sp.method })}
            className={`rounded-lg px-3 py-1.5 ${b === range.bucket ? "bg-brand-500/20 font-medium text-brand-200" : "text-slate-400 hover:bg-white/[0.04]"}`}
          >
            per {b}
          </Link>
        ))}
      </div>

      <p className="rounded-lg border border-amber-500/30 bg-amber-500/[0.06] px-3 py-2 text-xs text-amber-200">
        Small, young history: renewals have only been recorded since {fmtDay(data.earliestEvidence)}, so every rate here sits on a handful of
        renewals — read them as early signals. Amounts are what the sweep charges: VPS / game renewals include the owner&apos;s VAT/GST and any
        partner or retention discount (lib/renewal-charge.ts); hosting / email / domain / volume renewals carry no tax. Removed services are
        priced at their last known renewal or catalog price (marked est.).
      </p>

      <div className="grid grid-cols-2 gap-4 xl:grid-cols-4">
        <StatCard label="Renewing · next 7 days" value={`${up7.count} · ${fmtMoney(up7.cents)}`} delta={`${up7.atRisk} at risk (${fmtMoney(up7.atRiskCents)})`} deltaGood={up7.atRisk === 0} href={drillHref("upcoming7")} />
        <StatCard label="Renewing · next 30 days" value={`${up30.count} · ${fmtMoney(up30.cents)}`} delta={`${up30.atRisk} at risk (${fmtMoney(up30.atRiskCents)})`} deltaGood={up30.atRisk === 0} href={drillHref("upcoming30")} />
        <StatCard label="Auto-renew off · next 30 days" value={`${up30.autoRenewOff} · ${fmtMoney(up30.autoRenewOffCents)}`} delta="expected voluntary churn unless turned back on" deltaGood={up30.autoRenewOff === 0} href={drillHref("upcoming30")} />
        <StatCard label="Payment success · last 30 / 90 days" value={`${pct(paymentSuccessRate(t30))} / ${pct(paymentSuccessRate(t90))}`} delta={`failure ${pct(failureRate(t30))} / ${pct(failureRate(t90))}`} deltaGood={(failureRate(t30) ?? 0) === 0} />
      </div>

      <div className="grid grid-cols-2 gap-4 xl:grid-cols-4">
        <StatCard label={`Renewal rate · ${range.label.toLowerCase()}`} value={pct(renewalRate(t))} delta={`${t.renewed} renewed of ${t.renewed + t.failed + t.voluntary} decided`} deltaGood={(renewalRate(t) ?? 1) >= 0.7} href={drillHref("all")} />
        <StatCard label="Payment success rate" value={pct(paymentSuccessRate(t))} delta={`${t.failed} failed charge${t.failed === 1 ? "" : "s"} → churn`} deltaGood={t.failed === 0} href={drillHref("failed")} />
        <StatCard label="Revenue retained" value={pct(revenueRetained(t))} delta={`${fmtMoney(t.collectedCents)} collected of ${fmtMoney(t.dueCents)} due`} deltaGood={(revenueRetained(t) ?? 1) >= 0.7} href={drillHref("renewed")} />
        <StatCard label="Recovered after a failure" value={String(t.recovered)} delta={`${t.pending} pending in dunning / grace`} deltaGood href={drillHref("recovered")} />
      </div>

      <Section title="Renewals over time" sub={`Each renewal counted when it was decided (due date, or the day it was paid / cancelled if earlier), per ${range.bucket}.`}>
        <AreaChart
          id="ren-buckets"
          height={200}
          series={[
            { name: "Renewed", data: buckets.tallies.map((x) => x.renewed), color: "#34d399" },
            { name: "Failed", data: buckets.tallies.map((x) => x.failed), color: "#fb7185" },
            { name: "Voluntary", data: buckets.tallies.map((x) => x.voluntary), color: "#fbbf24" },
          ]}
          xLabels={axisLabels(buckets.keys)}
          yLabel={(v) => v.toFixed(0)}
        />
        <div className="mt-2 flex flex-wrap gap-4 text-xs text-slate-400">
          <span><span className="mr-1 inline-block h-2 w-2 rounded-full bg-emerald-400" />Renewed</span>
          <span><span className="mr-1 inline-block h-2 w-2 rounded-full bg-rose-400" />Failed (involuntary)</span>
          <span><span className="mr-1 inline-block h-2 w-2 rounded-full bg-amber-400" />Voluntary churn</span>
        </div>
        <div className="mt-4">
          <Table
            head={[range.bucket === "week" ? "Week of" : "Month", ...rateHead.slice(1)]}
            rows={buckets.keys
              .map((k, i) => ({ k, x: buckets.tallies[i] }))
              .reverse()
              .map(({ k, x }) => rateRow(shortKey(k), x, { b: k }))}
          />
        </div>
      </Section>

      <div className="grid gap-6 xl:grid-cols-2">
        <Section title="By product" sub="Every renewable product in the schema; each renews through its own sweep.">
          <Table
            head={["Product", "Renewed", "Failed", "Voluntary", "Renewal rate", "Collected", "Next 30d"]}
            rows={PRODUCTS.map((p) => ({ p, x: byProduct.get(p) }))
              .filter(({ p, x }) => x || cycles.some((c) => c.product === p))
              .map(({ p, x }) => {
                const xx = x ?? tallyWindow([], range.from, end);
                const up = upcomingWithin(cycles.filter((c) => c.product === p), now, 30);
                return [
                  PRODUCT_LABEL[p],
                  numLink(xx.renewed, drillHref("renewed", { product: p })),
                  numLink(xx.failed, drillHref("failed", { product: p })),
                  numLink(xx.voluntary, drillHref("voluntary", { product: p })),
                  pct(renewalRate(xx)),
                  fmtMoney(xx.collectedCents),
                  up.count ? <Link className="text-brand-300 hover:text-brand-200" href={drillHref("upcoming30", { product: p })}>{`${up.count} · ${fmtMoney(up.cents)}`}</Link> : "—",
                ];
              })}
          />
        </Section>

        <Section title="By payment method" sub="Renewed: how it was paid. Failed: the rail that failed (card = declined / unusable card; wallet = short balance and no card).">
          <Table
            head={["Method", "Renewed", "Failed", "Success rate", "Collected"]}
            rows={(["wallet", "card", "wallet+card", "paypal", "free"] as Method[])
              .filter((m) => byMethod.has(m))
              .map((m) => {
                const x = byMethod.get(m)!;
                return [METHOD_LABEL[m], numLink(x.renewed, drillHref("renewed", { method: m })), numLink(x.failed, drillHref("failed", { method: m })), pct(paymentSuccessRate(x)), fmtMoney(x.collectedCents)];
              })}
            empty="No renewals decided in this range."
          />
          <div className="mt-4 grid grid-cols-2 gap-3 text-sm sm:grid-cols-4">
            <div><p className="text-xs text-slate-500">Card charge attempts</p><p className="font-semibold tabular-nums">{card.attempts}</p></div>
            <div><p className="text-xs text-slate-500">Succeeded</p><p className="font-semibold tabular-nums">{card.succeeded}</p></div>
            <div><p className="text-xs text-slate-500">Declined / unusable</p><p className="font-semibold tabular-nums">{card.declined} / {card.unusable}</p></div>
            <div><p className="text-xs text-slate-500">Attempt decline rate</p><p className="font-semibold tabular-nums">{pct(card.declineRate)}</p></div>
          </div>
          <p className="mt-3 text-xs text-slate-500">
            PayPal is a renewal fallback only when the <code>renewals_paypal_fallback_enabled</code> setting is on; it appears here only once a PayPal renewal exists.
          </p>
        </Section>
      </div>

      <Section title="Churn: involuntary vs voluntary" sub="Involuntary = auto-renew was on but the money never arrived. Voluntary = the customer turned auto-renew off, cancelled or deleted. Removals by Nxeon (fraud, abuse, admin cleanup) are listed apart and excluded from the rates.">
        <div className="grid gap-4 md:grid-cols-3">
          {(["failed", "voluntary", "admin"] as const).map((o) => {
            const n = o === "failed" ? t.failed : o === "voluntary" ? t.voluntary : t.admin;
            const lost = o === "failed" ? t.lostInvoluntaryCents : o === "voluntary" ? t.lostVoluntaryCents : null;
            return (
              <div key={o} className="rounded-xl border border-white/[0.07] bg-white/[0.02] p-4">
                <p className={`text-sm font-semibold ${OUTCOME_TONE[o]}`}>{OUTCOME_LABEL[o]}</p>
                <p className="mt-1 text-2xl font-bold tabular-nums">
                  <Link href={drillHref(o)} className="hover:text-brand-200">{n}</Link>
                  {lost != null && <span className="ml-2 text-sm font-medium text-slate-400">{fmtMoney(lost)} not collected</span>}
                </p>
                <ul className="mt-2 space-y-1 text-xs text-slate-400">
                  {churnReasons(o).slice(0, 5).map(([r, c]) => (
                    <li key={r} className="flex justify-between gap-2"><span className="truncate" title={r}>{r}</span><span className="tabular-nums">{c}</span></li>
                  ))}
                  {churnReasons(o).length === 0 && <li>None in this range.</li>}
                </ul>
              </div>
            );
          })}
        </div>
      </Section>

      <Section title="Cohort renewal curves" sub="By start month: of the services whose Nth renewal has been decided, the share that paid it (survived / reached). Most services are monthly, so renewal N ≈ month N+1. Pending, upcoming and Nxeon removals are left out, not counted as churn.">
        <Table
          head={["Started", "Services", ...Array.from({ length: maxK }, (_, i) => `Renewal ${i + 1}`)]}
          rows={cohorts.map((r) => [
            shortKey(r.month),
            r.services,
            ...r.cols.slice(0, maxK).map((c) =>
              c.eligible ? (
                <span title={`${c.survived} of ${c.eligible}`}>
                  <span className="font-semibold">{pct(c.survived / c.eligible)}</span> <span className="text-xs text-slate-500">{c.survived}/{c.eligible}</span>
                </span>
              ) : (
                <span className="text-slate-600">·</span>
              ),
            ),
          ])}
          empty="No paid services yet."
        />
      </Section>

      <section id="drill" className="card scroll-mt-24">
        <div className="mb-3 flex flex-wrap items-baseline justify-between gap-2">
          <div>
            <h2 className="font-semibold">{DRILL_LABEL[drill]}</h2>
            <p className="mt-0.5 text-xs text-slate-500">
              {drillRows.length} renewal{drillRows.length === 1 ? "" : "s"}
              {sp.product ? ` · ${PRODUCT_LABEL[sp.product as Product] ?? sp.product}` : ""}
              {sp.method ? ` · ${METHOD_LABEL[sp.method as Method] ?? sp.method}` : ""}
              {sp.b ? ` · ${shortKey(sp.b)}` : ""}
              {drill.startsWith("upcoming") ? "" : ` · ${range.label.toLowerCase()}`}
            </p>
          </div>
          <div className="flex flex-wrap gap-1 text-xs">
            {DRILL_KINDS.map((k) => (
              <Link key={k} href={drillHref(k)} className={`rounded-md px-2 py-1 ${k === drill && !sp.product && !sp.method && !sp.b ? "bg-brand-500/20 text-brand-200" : "text-slate-400 hover:bg-white/[0.04]"}`}>
                {DRILL_LABEL[k].split(" — ")[0] === "Upcoming" ? DRILL_LABEL[k].replace("Upcoming — next ", "Next ") : DRILL_LABEL[k].split(" (")[0]}
              </Link>
            ))}
          </div>
        </div>
        <Table
          head={["Customer", "Service", "Product", "Renewal #", "Due", "Settled", "Outcome", "Amount", "Paid by / funding", "Why"]}
          rows={drillRows.slice(0, 300).map((c: Cycle) => {
            const u = data.users.get(c.userId);
            const link = data.links.get(c.serviceKey);
            return [
              <Link key="u" href={`/admin/users/${c.userId}`} className="font-medium hover:text-brand-300" title={u?.email}>
                {u?.name || u?.email || c.userId}
              </Link>,
              link ? (
                <Link key="s" href={link} className="text-brand-300 hover:text-brand-200">{c.label}</Link>
              ) : (
                <span key="s" className="text-slate-400" title="No longer exists">{c.label}</span>
              ),
              PRODUCT_LABEL[c.product],
              c.index,
              fmtDay(c.dueAt),
              fmtDay(c.resolvedAt),
              <span key="o" className={OUTCOME_TONE[c.outcome]}>
                {OUTCOME_LABEL[c.outcome]}
                {c.recovered ? " · recovered" : ""}
                {c.early ? " · early" : ""}
              </span>,
              `${fmtMoney(c.amountCents)}${c.estimated ? " est." : ""}`,
              c.outcome === "renewed"
                ? METHOD_LABEL[c.method ?? "wallet"]
                : c.outcome === "failed"
                  ? `${c.failRail ?? "wallet"} failed${c.failures ? ` ×${c.failures}` : ""}`
                  : c.outcome === "upcoming"
                    ? c.autoRenewAtDue === false
                      ? "auto-renew off"
                      : c.funding === "at_risk"
                        ? "AT RISK: wallet short, no card"
                        : c.funding === "card"
                          ? "card on file"
                          : "wallet covers it"
                    : "—",
              <span key="w" className="text-xs text-slate-400">{c.reason}</span>,
            ];
          })}
          empty="Nothing here for this selection."
        />
        {drillRows.length > 300 && <p className="mt-2 text-xs text-slate-500">Showing the first 300.</p>}
      </section>

      <p className="text-xs text-slate-500">
        Definitions: renewal rate = renewed ÷ (renewed + failed + voluntary); payment success = renewed ÷ (renewed + failed); revenue retained = collected ÷
        (collected + expected amount of failed and voluntary renewals). &ldquo;At risk&rdquo; = auto-renew on, wallet below the renewal and no chargeable card
        (email, domain and volume renewals are wallet-only). Excluded: {data.excluded.nonRealServices} services owned by internal / QA / flagged accounts,{" "}
        {data.excluded.freeOrGranted} free or partner-granted servers. Full method in the admin docs, &ldquo;Renewal analytics&rdquo;.
      </p>
    </div>
  );
}

