import { test } from "node:test";
import assert from "node:assert/strict";
import {
  addMonthsUtc,
  bucketKey,
  bucketKeys,
  buildCycles,
  cardAttemptStats,
  cohortCurves,
  drillCycles,
  hostnameFromDescription,
  paymentSuccessRate,
  parseAdminRenewDetail,
  parseAutoRenewToggle,
  parseBillingDetail,
  parseDeclineDetail,
  parseRange,
  renewalRate,
  revenueRetained,
  scopeToRealUsers,
  tallyBy,
  tallyByBucket,
  tallyWindow,
  termFromOrderDetail,
  upcomingWithin,
  methodKey,
  type ServiceInput,
  type SuccessInput,
  type FailureInput,
  type AutoRenewEvent,
} from "../lib/renewal-analytics-core.ts";

const DAY = 86_400_000;
const NOW = new Date("2026-10-07T12:00:00Z");
const d = (s: string) => new Date(s);
const ID = (n: number) => `cmt${String(n).padStart(22, "0")}`;

function svc(over: Partial<ServiceInput> & { id: string }): ServiceInput {
  return {
    key: `server:${over.id}`,
    product: "vps",
    userId: "u1",
    label: over.id,
    startedAt: d("2026-08-01T00:00:00Z"),
    termMonths: 1,
    alive: true,
    suspended: false,
    expiresAt: d("2026-11-01T00:00:00Z"),
    autoRenewNow: true,
    endedAt: null,
    endKind: null,
    expectedCents: 1000,
    funding: "wallet",
    ...over,
  };
}
function ok(id: string, at: string, due: string | null, over: Partial<SuccessInput> = {}): SuccessInput {
  return { serviceKey: `server:${id}`, at: d(at), dueAt: due ? d(due) : null, amountCents: 1000, method: "wallet", cardCents: 0, walletCents: 1000, source: "sweep", ...over };
}

/* ---------------- parsing the real audit formats ---------------- */

test("parseBillingDetail: server id, hosting/email/volume with amount + new expiry", () => {
  assert.deepEqual(parseBillingDetail("cmt9ss7ln000xhlrx0gch9fcx"), { product: "server", id: "cmt9ss7ln000xhlrx0gch9fcx", amountCents: null, newExpiry: null });
  assert.deepEqual(parseBillingDetail("hosting cmsnfpyf00006hlxn3p5vf1kb kaymo.revsports.ca $2.99 -> 2026-10-10"), {
    product: "hosting",
    id: "cmsnfpyf00006hlxn3p5vf1kb",
    amountCents: 299,
    newExpiry: "2026-10-10",
  });
  assert.equal(parseBillingDetail("email cmspmyvb7000fhluiwquz356z kaymo.revsports.ca $0.00 -> 2026-10-10")?.amountCents, 0);
  assert.equal(parseBillingDetail("hosting cmtbeqi1v03bmhltydtnpqhxi abc.sites.nxeon.cloud")?.product, "hosting");
  assert.equal(parseBillingDetail(""), null);
  assert.equal(parseBillingDetail("something else"), null);
});

test("parseDeclineDetail / parseAdminRenewDetail / parseAutoRenewToggle", () => {
  const dec = parseDeclineDetail("cmt9yxvnc0054hlrxafzd6asf: attempt 2 for $15.98 — Your card was declined.");
  assert.deepEqual(dec, { serverId: "cmt9yxvnc0054hlrxafzd6asf", attempt: 2, amountCents: 1598, message: "Your card was declined." });
  const okA = parseAdminRenewDetail("cmtem49d200b7hlylo2hmcebh (darkeden-guard-sg) renewed via wallet+card — wallet $6.12 + card $21.37 = $27.49, new expiry 2026-10-29");
  assert.deepEqual(okA, { serverId: "cmtem49d200b7hlylo2hmcebh", ok: true, path: "wallet+card", walletCents: 612, cardCents: 2137, totalCents: 2749 });
  const bad = parseAdminRenewDetail("cmtd1vsbb12gnhluynmdhqi5r (mobilkit) FAILED — declined: Your card has insufficient funds.");
  assert.equal(bad && !bad.ok && bad.reason, "declined");
  assert.deepEqual(parseAutoRenewToggle("cmuevsfqn0s6uhl7a5u3vistu -> false"), { serverId: "cmuevsfqn0s6uhl7a5u3vistu", on: false });
});

test("hostnameFromDescription + termFromOrderDetail", () => {
  assert.equal(hostnameFromDescription("Palworld — 16 GB / 32 players Game Server (palworld-0y55qe) — Monthly"), "palworld-0y55qe");
  assert.equal(hostnameFromDescription("Custom VPS (syntech-vps), first month, 50% off (COMEBACK50)"), "syntech-vps");
  assert.equal(hostnameFromDescription("Wallet top-up"), null);
  assert.equal(termFromOrderDetail("cmx game=valheim tier=Valheim — 8 GB term=12mo card"), 12);
  assert.equal(termFromOrderDetail("cmx plan=nano free=false"), 1);
});

/* ---------------- real-customer scoping ---------------- */

test("scopeToRealUsers drops flagged / internal / unknown owners", () => {
  const real = new Set(["u1", "u2"]);
  const rows = [{ userId: "u1" }, { userId: "owner-flagged" }, { userId: null }, { userId: "u2" }];
  assert.deepEqual(scopeToRealUsers(rows, real).map((r) => r.userId), ["u1", "u2"]);
});

test("a flagged (excludeFromRevenue) user's renewals never reach a tally", () => {
  const real = new Set(["u1"]);
  const services = scopeToRealUsers(
    [svc({ id: ID(1), userId: "u1", expiresAt: d("2026-11-01T00:00:00Z") }), svc({ id: ID(2), userId: "qa", expiresAt: d("2026-11-01T00:00:00Z") })],
    real,
  );
  const cycles = buildCycles(services, [ok(ID(1), "2026-10-01T00:05:00Z", "2026-10-01T00:00:00Z"), ok(ID(2), "2026-10-01T00:05:00Z", "2026-10-01T00:00:00Z")], [], [], { now: NOW });
  const t = tallyWindow(cycles, d("2026-09-01T00:00:00Z"), NOW);
  assert.equal(t.renewed, 1);
  assert.equal(t.collectedCents, 1000);
});

/* ---------------- classification ---------------- */

test("renewed on time vs early vs recovered after a decline", () => {
  const a = ID(10), b = ID(11), c = ID(12);
  const cycles = buildCycles(
    [svc({ id: a }), svc({ id: b }), svc({ id: c })],
    [
      ok(a, "2026-10-01T00:10:00Z", "2026-10-01T00:00:00Z"),
      ok(b, "2026-09-25T00:00:00Z", "2026-10-01T00:00:00Z", { method: "card", cardCents: 1000, walletCents: 0, source: "admin" }),
      ok(c, "2026-10-04T00:00:00Z", "2026-10-01T00:00:00Z", { method: "card", cardCents: 1000, walletCents: 0 }),
    ],
    [{ serviceKey: `server:${c}`, at: d("2026-10-02T00:00:00Z"), kind: "card_declined", amountCents: 1000 }],
    [],
    { now: NOW },
  );
  const first = (id: string) => cycles.find((x) => x.serviceId === id && x.index === 1)!;
  assert.equal(first(a).outcome, "renewed");
  assert.equal(first(a).early, false);
  assert.equal(first(b).early, true);
  assert.equal(first(b).decidedAt.toISOString(), "2026-09-25T00:00:00.000Z", "an early renewal counts the day it was paid");
  assert.equal(first(c).recovered, true);
  assert.equal(first(c).failures, 1);
  // Each has a second, upcoming cycle at its current expiry.
  assert.equal(cycles.filter((x) => x.outcome === "upcoming").length, 3);
});

test("alive + unpaid: suspended -> failed, recent -> pending, auto-renew off -> voluntary", () => {
  const s1 = ID(20), s2 = ID(21), s3 = ID(22), s4 = ID(23);
  const cycles = buildCycles(
    [
      svc({ id: s1, expiresAt: d("2026-09-20T00:00:00Z"), suspended: true }),
      svc({ id: s2, expiresAt: d("2026-10-05T00:00:00Z") }),
      svc({ id: s3, expiresAt: d("2026-10-01T00:00:00Z"), autoRenewNow: false }),
      svc({ id: s4, expiresAt: d("2026-09-01T00:00:00Z") }),
    ],
    [],
    [
      { serviceKey: `server:${s1}`, at: d("2026-09-21T00:00:00Z"), kind: "card_declined" },
      { serviceKey: `server:${s1}`, at: d("2026-09-27T00:00:00Z"), kind: "suspended_unpaid" },
      { serviceKey: `server:${s2}`, at: d("2026-10-06T00:00:00Z"), kind: "card_declined" },
    ],
    [],
    { now: NOW },
  );
  const o = (id: string) => cycles.find((x) => x.serviceId === id)!;
  assert.equal(o(s1).outcome, "failed");
  assert.equal(o(s1).failRail, "card");
  assert.equal(o(s2).outcome, "pending");
  assert.equal(o(s3).outcome, "voluntary");
  assert.equal(o(s4).outcome, "failed", "unpaid well past the grace window without a suspension is still a failure");
  assert.equal(o(s4).failRail, "wallet");
});

test("auto-renew history: the state AT the due date wins over today's flag", () => {
  const s = ID(30);
  const ev: AutoRenewEvent[] = [
    { serviceKey: `server:${s}`, at: d("2026-09-10T00:00:00Z"), on: false },
    { serviceKey: `server:${s}`, at: d("2026-10-03T00:00:00Z"), on: true },
