  const cycles = buildCycles([svc({ id: s, expiresAt: d("2026-10-01T00:00:00Z"), autoRenewNow: true })], [], [], ev, { now: NOW });
  assert.equal(cycles[0].outcome, "voluntary");
  assert.equal(cycles[0].autoRenewAtDue, false);
});

test("removed services: cancel before term end, lapse after a decline, admin removal, no record", () => {
  const a = ID(40), b = ID(41), c = ID(42), e = ID(43);
  const cycles = buildCycles(
    [
      svc({ id: a, alive: false, expiresAt: d("2026-10-20T00:00:00Z"), endedAt: d("2026-10-02T00:00:00Z"), endKind: "customer", autoRenewNow: null }),
