/* ---------------- rates, money, buckets ---------------- */

test("rates: null on empty, admin + pending excluded from the denominator", () => {
  const empty = tallyWindow([], d("2026-01-01"), NOW);
  assert.equal(renewalRate(empty), null);
  assert.equal(paymentSuccessRate(empty), null);
  assert.equal(revenueRetained(empty), null);

  const ids = [ID(50), ID(51), ID(52), ID(53), ID(54)];
  const cycles = buildCycles(
    [
      svc({ id: ids[0], expiresAt: d("2026-11-01T00:00:00Z") }),
      svc({ id: ids[1], expiresAt: d("2026-10-01T00:00:00Z"), suspended: true, expectedCents: 500 }),
      svc({ id: ids[2], expiresAt: d("2026-10-01T00:00:00Z"), autoRenewNow: false, expectedCents: 2000 }),
      svc({ id: ids[3], alive: false, expiresAt: d("2026-10-01T00:00:00Z"), endedAt: d("2026-10-02T00:00:00Z"), endKind: "admin" }),
      svc({ id: ids[4], expiresAt: d("2026-10-06T00:00:00Z") }),
    ],
    [ok(ids[0], "2026-10-01T00:05:00Z", "2026-10-01T00:00:00Z", { amountCents: 1000 })],
    [{ serviceKey: `server:${ids[1]}`, at: d("2026-10-04T00:00:00Z"), kind: "suspended_unpaid" }],
    [],
    { now: NOW },
  );
  const t = tallyWindow(cycles, d("2026-09-01T00:00:00Z"), NOW);
  assert.deepEqual([t.renewed, t.failed, t.voluntary, t.admin, t.pending], [1, 1, 1, 1, 1]);
  assert.equal(renewalRate(t), 1 / 3);
  assert.equal(paymentSuccessRate(t), 1 / 2);
  assert.equal(t.collectedCents, 1000);
  assert.equal(t.dueCents, 1000 + 500 + 2000);
  assert.equal(revenueRetained(t), 1000 / 3500);
  assert.equal(t.lostInvoluntaryCents, 500);
  assert.equal(t.lostVoluntaryCents, 2000);

  const byProduct = tallyBy(cycles, d("2026-09-01T00:00:00Z"), NOW, (c) => c.product);
  assert.equal(byProduct.get("vps")!.renewed, 1);
  const byMethod = tallyBy(cycles, d("2026-09-01T00:00:00Z"), NOW, methodKey);
  assert.equal(byMethod.get("wallet")!.renewed, 1);
  assert.equal(byMethod.get("wallet")!.failed, 1);
