  assert.deepEqual([u7.count, u7.cents, u7.atRisk, u7.autoRenewOff, u7.autoRenewOffCents], [1, 499, 1, 1, 900]);
  const u30 = upcomingWithin(cycles, NOW, 30);
  assert.deepEqual([u30.count, u30.cents, u30.cards, u30.atRisk], [2, 1798, 1, 1]);
