  hostnameFromDescription,
  paymentSuccessRate,
  parseAdminRenewDetail,
  parseAutoRenewToggle,
  parseBillingDetail,
  parseDeclineDetail,
  parseRange,
  renewalRate,
  revenueRetained,
  scopeToRealUsers,
  tallyBy,
  tallyByBucket,
  tallyWindow,
  termFromOrderDetail,
  upcomingWithin,
  methodKey,
  type ServiceInput,
  type SuccessInput,
  type FailureInput,
  type AutoRenewEvent,
} from "../lib/renewal-analytics-core.ts";

const DAY = 86_400_000;
const NOW = new Date("2026-10-07T12:00:00Z");
const d = (s: string) => new Date(s);
const ID = (n: number) => `cmt${String(n).padStart(22, "0")}`;

function svc(over: Partial<ServiceInput> & { id: string }): ServiceInput {
  return {
    key: `server:${over.id}`,
    product: "vps",
    userId: "u1",
    label: over.id,
    startedAt: d("2026-08-01T00:00:00Z"),
    termMonths: 1,
    alive: true,
    suspended: false,
    expiresAt: d("2026-11-01T00:00:00Z"),
    autoRenewNow: true,
    endedAt: null,
    endKind: null,
    expectedCents: 1000,
    funding: "wallet",
    ...over,
  };
}
function ok(id: string, at: string, due: string | null, over: Partial<SuccessInput> = {}): SuccessInput {
  return { serviceKey: `server:${id}`, at: d(at), dueAt: due ? d(due) : null, amountCents: 1000, method: "wallet", cardCents: 0, walletCents: 1000, source: "sweep", ...over };
}

/* ---------------- parsing the real audit formats ---------------- */

test("parseBillingDetail: server id, hosting/email/volume with amount + new expiry", () => {
  assert.deepEqual(parseBillingDetail("cmt9ss7ln000xhlrx0gch9fcx"), { product: "server", id: "cmt9ss7ln000xhlrx0gch9fcx", amountCents: null, newExpiry: null });
  assert.deepEqual(parseBillingDetail("hosting cmsnfpyf00006hlxn3p5vf1kb kaymo.revsports.ca $2.99 -> 2026-10-10"), {
    product: "hosting",
    id: "cmsnfpyf00006hlxn3p5vf1kb",
    amountCents: 299,
    newExpiry: "2026-10-10",
  });
  assert.equal(parseBillingDetail("email cmspmyvb7000fhluiwquz356z kaymo.revsports.ca $0.00 -> 2026-10-10")?.amountCents, 0);
  assert.equal(parseBillingDetail("hosting cmtbeqi1v03bmhltydtnpqhxi abc.sites.nxeon.cloud")?.product, "hosting");
  assert.equal(parseBillingDetail(""), null);
  assert.equal(parseBillingDetail("something else"), null);
});

test("parseDeclineDetail / parseAdminRenewDetail / parseAutoRenewToggle", () => {
  const dec = parseDeclineDetail("cmt9yxvnc0054hlrxafzd6asf: attempt 2 for $15.98 — Your card was declined.");
  assert.deepEqual(dec, { serverId: "cmt9yxvnc0054hlrxafzd6asf", attempt: 2, amountCents: 1598, message: "Your card was declined." });
  const okA = parseAdminRenewDetail("cmtem49d200b7hlylo2hmcebh (darkeden-guard-sg) renewed via wallet+card — wallet $6.12 + card $21.37 = $27.49, new expiry 2026-10-29");
  assert.deepEqual(okA, { serverId: "cmtem49d200b7hlylo2hmcebh", ok: true, path: "wallet+card", walletCents: 612, cardCents: 2137, totalCents: 2749 });
  const bad = parseAdminRenewDetail("cmtd1vsbb12gnhluynmdhqi5r (mobilkit) FAILED — declined: Your card has insufficient funds.");
  assert.equal(bad && !bad.ok && bad.reason, "declined");
  assert.deepEqual(parseAutoRenewToggle("cmuevsfqn0s6uhl7a5u3vistu -> false"), { serverId: "cmuevsfqn0s6uhl7a5u3vistu", on: false });
});

test("hostnameFromDescription + termFromOrderDetail", () => {
  assert.equal(hostnameFromDescription("Palworld — 16 GB / 32 players Game Server (palworld-0y55qe) — Monthly"), "palworld-0y55qe");
  assert.equal(hostnameFromDescription("Custom VPS (syntech-vps), first month, 50% off (COMEBACK50)"), "syntech-vps");
  assert.equal(hostnameFromDescription("Wallet top-up"), null);
  assert.equal(termFromOrderDetail("cmx game=valheim tier=Valheim — 8 GB term=12mo card"), 12);
  assert.equal(termFromOrderDetail("cmx plan=nano free=false"), 1);
