  const cycles = buildCycles(services, [ok(ID(1), "2026-10-01T00:05:00Z", "2026-10-01T00:00:00Z"), ok(ID(2), "2026-10-01T00:05:00Z", "2026-10-01T00:00:00Z")], [], [], { now: NOW });
  const t = tallyWindow(cycles, d("2026-09-01T00:00:00Z"), NOW);
  assert.equal(t.renewed, 1);
  assert.equal(t.collectedCents, 1000);
