/* ---------------- classification ---------------- */

test("renewed on time vs early vs recovered after a decline", () => {
  const a = ID(10), b = ID(11), c = ID(12);
  const cycles = buildCycles(
    [svc({ id: a }), svc({ id: b }), svc({ id: c })],
    [
      ok(a, "2026-10-01T00:10:00Z", "2026-10-01T00:00:00Z"),
      ok(b, "2026-09-25T00:00:00Z", "2026-10-01T00:00:00Z", { method: "card", cardCents: 1000, walletCents: 0, source: "admin" }),
