      svc({ id: b, alive: false, expiresAt: d("2026-10-04T00:00:00Z"), endedAt: d("2026-10-05T00:00:00Z"), endKind: "unknown", autoRenewNow: null }),
      svc({ id: c, alive: false, expiresAt: d("2026-09-26T00:00:00Z"), endedAt: d("2026-10-01T00:00:00Z"), endKind: "admin", endNote: "fraud teardown", autoRenewNow: null }),
