    ],
    [],
    [{ serviceKey: `server:${b}`, at: d("2026-10-04T01:00:00Z"), kind: "card_declined" }],
    [],
    { now: NOW },
  );
  const o = (id: string) => cycles.find((x) => x.serviceId === id)!;
  assert.equal(o(a).outcome, "voluntary");
  assert.equal(o(a).decidedAt.toISOString(), "2026-10-02T00:00:00.000Z", "a cancellation counts on the day it happened");
  assert.equal(o(b).outcome, "failed");
  assert.equal(o(c).outcome, "admin");
  assert.equal(o(e).outcome, "voluntary", "gone after its due date with no failed charge = the customer let it go");
});

/* ---------------- rates, money, buckets ---------------- */

test("rates: null on empty, admin + pending excluded from the denominator", () => {
  const empty = tallyWindow([], d("2026-01-01"), NOW);
  assert.equal(renewalRate(empty), null);
  assert.equal(paymentSuccessRate(empty), null);
  assert.equal(revenueRetained(empty), null);

  const ids = [ID(50), ID(51), ID(52), ID(53), ID(54)];
  const cycles = buildCycles(
    [
      svc({ id: ids[0], expiresAt: d("2026-11-01T00:00:00Z") }),
      svc({ id: ids[1], expiresAt: d("2026-10-01T00:00:00Z"), suspended: true, expectedCents: 500 }),
      svc({ id: ids[2], expiresAt: d("2026-10-01T00:00:00Z"), autoRenewNow: false, expectedCents: 2000 }),
      svc({ id: ids[3], alive: false, expiresAt: d("2026-10-01T00:00:00Z"), endedAt: d("2026-10-02T00:00:00Z"), endKind: "admin" }),
      svc({ id: ids[4], expiresAt: d("2026-10-06T00:00:00Z") }),
    ],
    [ok(ids[0], "2026-10-01T00:05:00Z", "2026-10-01T00:00:00Z", { amountCents: 1000 })],
    [{ serviceKey: `server:${ids[1]}`, at: d("2026-10-04T00:00:00Z"), kind: "suspended_unpaid" }],
    [],
    { now: NOW },
  );
  const t = tallyWindow(cycles, d("2026-09-01T00:00:00Z"), NOW);
  assert.deepEqual([t.renewed, t.failed, t.voluntary, t.admin, t.pending], [1, 1, 1, 1, 1]);
  assert.equal(renewalRate(t), 1 / 3);
  assert.equal(paymentSuccessRate(t), 1 / 2);
  assert.equal(t.collectedCents, 1000);
  assert.equal(t.dueCents, 1000 + 500 + 2000);
  assert.equal(revenueRetained(t), 1000 / 3500);
  assert.equal(t.lostInvoluntaryCents, 500);
  assert.equal(t.lostVoluntaryCents, 2000);

  const byProduct = tallyBy(cycles, d("2026-09-01T00:00:00Z"), NOW, (c) => c.product);
  assert.equal(byProduct.get("vps")!.renewed, 1);
  const byMethod = tallyBy(cycles, d("2026-09-01T00:00:00Z"), NOW, methodKey);
  assert.equal(byMethod.get("wallet")!.renewed, 1);
  assert.equal(byMethod.get("wallet")!.failed, 1);
});

test("weekly buckets start Monday UTC; monthly buckets; range presets", () => {
  assert.equal(bucketKey(d("2026-10-07T12:00:00Z"), "week"), "2026-10-05"); // Wednesday -> Monday
  assert.equal(bucketKey(d("2026-10-05T00:00:00Z"), "week"), "2026-10-05");
  assert.equal(bucketKey(d("2026-10-04T23:59:59Z"), "week"), "2026-09-28"); // Sunday -> previous Monday
  assert.equal(bucketKey(d("2026-10-31T23:00:00Z"), "month"), "2026-10");
  assert.deepEqual(bucketKeys(d("2026-09-15T00:00:00Z"), d("2026-10-07T00:00:00Z"), "week"), ["2026-09-14", "2026-09-21", "2026-09-28", "2026-10-05"]);
  assert.deepEqual(bucketKeys(d("2026-08-20T00:00:00Z"), d("2026-10-07T00:00:00Z"), "month"), ["2026-08", "2026-09", "2026-10"]);
  const r = parseRange({ range: "12m" }, NOW);
  assert.equal(r.bucket, "month");
  assert.equal(r.from.toISOString(), "2025-11-01T00:00:00.000Z");
  assert.equal(parseRange({}, NOW).key, "90d");
  assert.equal(parseRange({ range: "7d", bucket: "month" }, NOW).bucket, "month");
  assert.equal(parseRange({ range: "bogus" }, NOW).key, "90d");

  const s = ID(60);
  const cycles = buildCycles([svc({ id: s })], [ok(s, "2026-10-01T00:05:00Z", "2026-10-01T00:00:00Z")], [], [], { now: NOW });
  const b = tallyByBucket(cycles, parseRange({ range: "30d" }, NOW));
  const i = b.keys.indexOf("2026-09-28");
  assert.equal(b.tallies[i].renewed, 1);
  assert.equal(b.tallies.reduce((n, x) => n + x.renewed, 0), 1);
});

test("addMonthsUtc clamps month-end overflow", () => {
  assert.equal(addMonthsUtc(d("2026-01-31T00:00:00Z"), 1).toISOString(), "2026-02-28T00:00:00.000Z");
  assert.equal(addMonthsUtc(d("2026-08-15T10:00:00Z"), 12).toISOString(), "2027-08-15T10:00:00.000Z");
});

/* ---------------- upcoming ---------------- */

test("upcoming 7/30 days: auto-renew off counted apart, at-risk flagged", () => {
  const cycles = buildCycles(
    [
      svc({ id: ID(70), expiresAt: d("2026-10-10T00:00:00Z"), expectedCents: 499, funding: "at_risk" }),
      svc({ id: ID(71), expiresAt: d("2026-10-20T00:00:00Z"), expectedCents: 1299, funding: "card" }),
      svc({ id: ID(72), expiresAt: d("2026-10-12T00:00:00Z"), expectedCents: 900, autoRenewNow: false }),
      svc({ id: ID(73), expiresAt: d("2026-12-01T00:00:00Z"), expectedCents: 5000 }),
    ],
    [],
    [],
    [],
    { now: NOW },
  );
  const u7 = upcomingWithin(cycles, NOW, 7);
  assert.deepEqual([u7.count, u7.cents, u7.atRisk, u7.autoRenewOff, u7.autoRenewOffCents], [1, 499, 1, 1, 900]);
  const u30 = upcomingWithin(cycles, NOW, 30);
  assert.deepEqual([u30.count, u30.cents, u30.cards, u30.atRisk], [2, 1798, 1, 1]);
  assert.equal(drillCycles(cycles, { kind: "upcoming30" }, parseRange({}, NOW), NOW).length, 3);
});

/* ---------------- cohorts ---------------- */

test("cohort curves: survived / reached per renewal, censoring pending + admin", () => {
  const aug = d("2026-08-03T00:00:00Z");
  const a = svc({ id: ID(80), startedAt: aug, expiresAt: d("2026-11-03T00:00:00Z") }); // renewed twice
  const b = svc({ id: ID(81), startedAt: aug, alive: false, expiresAt: d("2026-09-03T00:00:00Z"), endedAt: d("2026-09-04T00:00:00Z"), endKind: "customer", autoRenewNow: null }); // churned at R1
  const c = svc({ id: ID(82), startedAt: aug, alive: false, expiresAt: d("2026-09-03T00:00:00Z"), endedAt: d("2026-09-10T00:00:00Z"), endKind: "admin", autoRenewNow: null }); // censored
  const e = svc({ id: ID(83), startedAt: d("2026-09-20T00:00:00Z"), expiresAt: d("2026-10-20T00:00:00Z") }); // not reached yet
  const services = [a, b, c, e];
  const cycles = buildCycles(
    services,
    [ok(a.id, "2026-09-03T00:05:00Z", "2026-09-03T00:00:00Z"), ok(a.id, "2026-10-03T00:05:00Z", "2026-10-03T00:00:00Z")],
    [],
    [],
    { now: NOW },
  );
  const rows = cohortCurves(services, cycles, NOW, 3);
  const augRow = rows.find((r) => r.month === "2026-08")!;
  assert.equal(augRow.services, 3);
  assert.deepEqual(augRow.cols[0], { survived: 1, eligible: 2 }, "R1: a paid, b churned, c censored");
  assert.deepEqual(augRow.cols[1], { survived: 1, eligible: 2 }, "R2: b still counts as gone once its R2 date has passed");
  assert.deepEqual(augRow.cols[2], { survived: 0, eligible: 0 }, "R3 not reached by anyone yet");
  const sepRow = rows.find((r) => r.month === "2026-09")!;
  assert.deepEqual(sepRow.cols[0], { survived: 0, eligible: 0 });
  assert.equal(rows[0].month, "2026-09", "newest cohort first");
});

/* ---------------- attempts + drill ---------------- */

test("card attempt stats + drill filters (product, method, bucket, recovered)", () => {
  const s1 = ID(90), s2 = ID(91);
  const successes = [
    ok(s1, "2026-10-03T00:00:00Z", "2026-10-01T00:00:00Z", { method: "card", cardCents: 1000, walletCents: 0 }),
    ok(s2, "2026-10-01T00:05:00Z", "2026-10-01T00:00:00Z"),
  ];
  const failures: FailureInput[] = [
    { serviceKey: `server:${s1}`, at: d("2026-10-01T01:00:00Z"), kind: "card_declined" },
    { serviceKey: `server:${s1}`, at: d("2026-10-02T01:00:00Z"), kind: "card_unusable" },
  ];
  const st = cardAttemptStats(successes, failures, d("2026-09-01T00:00:00Z"), NOW);
  assert.deepEqual(st, { attempts: 3, declined: 1, unusable: 1, succeeded: 1, declineRate: 2 / 3 });

  const cycles = buildCycles([svc({ id: s1 }), svc({ id: s2, product: "game", key: `server:${s2}` })], successes, failures, [], { now: NOW });
  const range = parseRange({ range: "30d" }, NOW);
  assert.equal(drillCycles(cycles, { kind: "renewed" }, range, NOW).length, 2);
  assert.equal(drillCycles(cycles, { kind: "renewed", product: "game" }, range, NOW).length, 1);
  assert.equal(drillCycles(cycles, { kind: "renewed", method: "card" }, range, NOW)[0].serviceId, s1);
  assert.equal(drillCycles(cycles, { kind: "recovered" }, range, NOW)[0].serviceId, s1);
  assert.equal(drillCycles(cycles, { kind: "renewed", bucket: "2026-09-28" }, range, NOW).length, 2);
  assert.equal(drillCycles(cycles, { kind: "renewed", bucket: "2026-10-05" }, range, NOW).length, 0);
});

