// Seeds the THROWAWAY DB (nxeon_pb1007) with a realistic renewal history for
// screenshots. Refuses to run against anything else. Not committed.
import { PrismaClient } from "@prisma/client";

const url = process.env.DATABASE_URL ?? "";
if (!/\/nxeon_pb1007(\?|$)/.test(url)) {
  console.error("refusing: DATABASE_URL is not the throwaway nxeon_pb1007 DB");
  process.exit(1);
}
const db = new PrismaClient();
const DAY = 86_400_000;
const now = Date.now();
const ago = (d: number, h = 0) => new Date(now - d * DAY - h * 3_600_000);
const ahead = (d: number, h = 0) => new Date(now + d * DAY + h * 3_600_000);
const addM = (d: Date, m: number) => {
  const x = new Date(d);
  x.setUTCMonth(x.getUTCMonth() + m);
  return x;
};
let piN = 0;

async function main() {
  // wipe only what this script creates (per-object DML, never cluster DDL)
  const tag = "@seed-renewals.example";
  const old = await db.user.findMany({ where: { email: { endsWith: "@renewals-seed.dev" } }, select: { id: true } });
  const oldIds = old.map((u) => u.id);
  if (oldIds.length) {
    await db.auditLog.deleteMany({ where: { userId: { in: oldIds } } });
    await db.invoice.deleteMany({ where: { userId: { in: oldIds } } });
    await db.walletTransaction.deleteMany({ where: { userId: { in: oldIds } } });
    await db.hostingAccount.deleteMany({ where: { userId: { in: oldIds } } });
    await db.emailSubscription.deleteMany({ where: { userId: { in: oldIds } } });
    await db.server.deleteMany({ where: { userId: { in: oldIds } } });
    await db.user.deleteMany({ where: { id: { in: oldIds } } });
  }
  void tag;

  const osT = await db.osTemplate.upsert({ where: { slug: "ubuntu-24-04" }, update: {}, create: { slug: "ubuntu-24-04", name: "Ubuntu 24.04", vmid: 9000 } });
  const starter = await db.plan.upsert({ where: { slug: "starter" }, update: { priceCents: 599 }, create: { slug: "starter", name: "Starter", cpuCores: 1, ramMB: 2048, diskGB: 40, priceCents: 599 } });
  const standard = await db.plan.upsert({ where: { slug: "standard" }, update: { priceCents: 1299 }, create: { slug: "standard", name: "Standard", cpuCores: 2, ramMB: 4096, diskGB: 80, priceCents: 1299 } });
  const pro = await db.plan.upsert({ where: { slug: "pro" }, update: { priceCents: 2499 }, create: { slug: "pro", name: "Pro", cpuCores: 4, ramMB: 8192, diskGB: 160, priceCents: 2499 } });
  const gp = async (name: string, fam: string, cents: number) =>
    (await db.gamePlan.findFirst({ where: { name } })) ?? db.gamePlan.create({ data: { name, gameFamily: fam, ramMB: 4096, diskGB: 40, priceCents: cents, basePlanId: standard.id } });
  const mc = await gp("Minecraft — 4 GB", "minecraft", 899);
  const valheim = await gp("Valheim — 4 GB / 10 players", "valheim", 999);
  const rust = await gp("Rust — 8 GB / 50 slots", "rust", 1899);
  const node = (await db.hostingNode.findFirst({ where: { name: "seed-web-1" } })) ?? (await db.hostingNode.create({ data: { name: "seed-web-1", publicIp: "203.0.113.10", sshHost: "203.0.113.10" } }));
  const hStarter = await db.hostingPlan.upsert({ where: { slug: "starter" }, update: {}, create: { slug: "starter", name: "Starter", priceCents: 299 } });
  const hBiz = await db.hostingPlan.upsert({ where: { slug: "business" }, update: {}, create: { slug: "business", name: "Business", priceCents: 899 } });
  const ePlan = (await db.emailPlan.findFirst({ where: { name: "Starter" } })) ?? (await db.emailPlan.create({ data: { name: "Starter", priceCents: 199 } }));

  const mkUser = (email: string, name: string, o: Record<string, unknown> = {}) =>
    db.user.create({ data: { email: `${email}@renewals-seed.dev`, passwordHash: "x", name, ...o } });
  const card = { stripeCustomerId: "cus_seed", stripePaymentMethodId: "pm_seed", cardBrand: "visa", cardLast4: "4242", cardExpMonth: 12, cardExpYear: 2029 };

  const admin = await db.user.findFirst({ where: { role: "ADMIN" } });
  const alice = await mkUser("alice", "Alice Moreau", { ...card, createdAt: ago(100) });
  const bob = await mkUser("bob", "Bob Tanaka", { ...card, createdAt: ago(80) });
  const carol = await mkUser("carol", "Carol Nguyen", { createdAt: ago(70) });
  const dave = await mkUser("dave", "Dave Okafor", { balanceCents: 0, createdAt: ago(45) });
  const erin = await mkUser("erin", "Erin Silva", { balanceCents: 150, createdAt: ago(75) });
  const frank = await mkUser("frank", "Frank Weber", { balanceCents: 2000, createdAt: ago(95) });
  const gina = await mkUser("gina", "Gina Rossi", { ...card, createdAt: ago(50) });
  const hank = await mkUser("hank", "Hank Patel", { ...card, createdAt: ago(40) });
  const ivan = await mkUser("ivan", "Ivan Petrov", { ...card, createdAt: ago(60) });
  const jun = await mkUser("jun", "Jun Park", { balanceCents: 5000, createdAt: ago(20) });
  const kim = await mkUser("kim", "Kim Larsen", { createdAt: ago(25) });
  const leo = await mkUser("leo", "Leo Martin", { ...card, createdAt: ago(10) });
  const owner = await mkUser("owner", "Owner (QA, excluded)", { ...card, excludeFromRevenue: true, createdAt: ago(110) });

  const audit = (userId: string | null, action: string, detail: string, at: Date) => db.auditLog.create({ data: { userId, action, detail, createdAt: at } });
  const invoice = (userId: string, description: string, cents: number, at: Date, ps: Date, pe: Date, renewalCents?: number) =>
    db.invoice.create({ data: { userId, description, amountCents: cents, status: "PAID", lineItems: [{ description, qty: 1, unitCents: cents, amountCents: cents }], periodStart: ps, periodEnd: pe, paidAt: at, createdAt: at, renewalCents: renewalCents ?? null } });
  const debit = (userId: string, description: string, cents: number, at: Date) => db.walletTransaction.create({ data: { userId, amountCents: -cents, description, createdAt: at } });
  const cardCredit = (userId: string, host: string, cents: number, at: Date) =>
    db.walletTransaction.create({ data: { userId, amountCents: cents, description: `Card payment for ${host} renewal (Visa ···· 4242, expires 12/29)`, stripePaymentIntentId: `pi_seed_${++piN}_${now}`, createdAt: at } });

  type SrvO = { user: { id: string }; host: string; plan: { id: string }; game?: { id: string; name: string } | null; created: Date; exp: Date; autoRenew?: boolean; status?: "RUNNING" | "SUSPENDED" | "STOPPED"; term?: number; free?: boolean };
  const server = (o: SrvO) =>
    db.server.create({
      data: {
        name: o.host,
        hostname: o.host,
        status: o.status ?? "RUNNING",
        userId: o.user.id,
        planId: o.plan.id,
        osTemplateId: osT.id,
        gamePlanId: o.game?.id ?? null,
        createdAt: o.created,
        expiresAt: o.exp,
        autoRenew: o.autoRenew ?? true,
        termMonths: o.term ?? 1,
        isFree: o.free ?? false,
        suspendReason: o.status === "SUSPENDED" ? "UNPAID" : null,
      },
    });
  // A renewal exactly as commitRenewal writes it (+ optional card leg first).
  const renew = async (s: { id: string; userId: string; hostname: string }, label: string, cents: number, due: Date, paidAt: Date, cardCents = 0, viaAdmin = false) => {
    if (cardCents > 0) await cardCredit(s.userId, s.hostname, cardCents, new Date(paidAt.getTime() - 2000));
    await debit(s.userId, `Renewal: ${label} (${s.hostname})`, cents, paidAt);
    await invoice(s.userId, `Renewal: ${label} (${s.hostname})`, cents, paidAt, due, addM(due, 1));
    await audit(s.userId, "billing.renewed", s.id, new Date(paidAt.getTime() + 5));
    if (viaAdmin && admin) {
      const path = cardCents === 0 ? "wallet" : cardCents >= cents ? "card" : "wallet+card";
      await audit(admin.id, "admin.renew_now", `${s.id} (${s.hostname}) renewed via ${path} — wallet $${((cents - cardCents) / 100).toFixed(2)} + card $${(cardCents / 100).toFixed(2)} = $${(cents / 100).toFixed(2)}, new expiry ${addM(due, 1).toISOString().slice(0, 10)}`, new Date(paidAt.getTime() + 2000));
    }
  };

  // Alice: Minecraft since ~95 days, renewed 3x by card, next renewal in 4 days (card on file).
  {
    const start = ago(95);
    const s = await server({ user: alice, host: "alice-mc", plan: standard, game: mc, created: start, exp: addM(start, 4) });
    for (let k = 1; k <= 3; k++) await renew(s, "Minecraft — 4 GB", 899, addM(start, k), new Date(addM(start, k).getTime() + 8 * 60_000), 899);
  }
  // Bob: VPS since ~70 days. R1 wallet+card, R2 declined x2, suspended unpaid -> involuntary.
  {
    const start = ago(70);
    const s = await server({ user: bob, host: "bob-vps", plan: standard, created: start, exp: addM(start, 2), status: "SUSPENDED" });
    await renew(s, "Standard VPS", 1299, addM(start, 1), new Date(addM(start, 1).getTime() + 10 * 60_000), 799);
    const due2 = addM(start, 2);
    await audit(bob.id, "billing.card_declined", `${s.id}: attempt 1 for $12.99 — Your card was declined.`, new Date(due2.getTime() + 600_000));
    await audit(bob.id, "billing.card_declined", `${s.id}: attempt 2 for $12.99 — Your card has insufficient funds.`, new Date(due2.getTime() + 3 * DAY));
    await audit(bob.id, "billing.suspended_unpaid", s.id, new Date(due2.getTime() + 7 * DAY));
  }
  // Carol: Valheim, renewed once by wallet, then "cancel at period end" -> lapsed (voluntary).
  {
    const start = ago(66);
    const s = await server({ user: carol, host: "carol-valheim", plan: standard, game: valheim, created: start, exp: addM(start, 2), autoRenew: false, status: "SUSPENDED" });
    await renew(s, "Valheim — 4 GB / 10 players", 999, addM(start, 1), new Date(addM(start, 1).getTime() + 5 * 60_000));
    await audit(carol.id, "server.cancel_period_end", s.id, ago(20));
  }
  // Dave: VPS ordered 28 days ago, cancelled immediately 9 days ago (row gone) -> voluntary before term end.
  {
    const at = ago(28);
    const id = "cmseeddave0000000000000001";
    await invoice(dave.id, "Starter VPS (dave-box) — Monthly", 599, at, at, addM(at, 1), 599);
    await audit(dave.id, "server.order", `${id} image=ubuntu-24-04 plan=starter term=1mo extraDisk=0GB free=false`, new Date(at.getTime() + 20));
    await audit(dave.id, "server.cancel_immediate", `${id} refund=210`, ago(9));
  }
  // Ivan: Rust ordered 40 days ago, card declined at renewal, fraud teardown -> removed by Nxeon.
  {
    const at = ago(40);
    const id = "cmseedivan0000000000000001";
    await invoice(ivan.id, "Rust — 8 GB / 50 slots Game Server (ivan-rust) — Monthly", 1899, at, at, addM(at, 1), 1899);
    await audit(ivan.id, "gameserver.order", `${id} game=rust tier=Rust — 8 GB / 50 slots term=1mo card region=fsn1`, new Date(at.getTime() + 20));
    await audit(ivan.id, "billing.card_declined", `${id}: attempt 1 for $18.99 — Your card was declined.`, new Date(addM(at, 1).getTime() + 600_000));
    if (admin) await audit(admin.id, "admin.fraud_teardown", `ivan-rust (vmid 999, primary) deleted by owner instruction: fraudulent card use detected.`, new Date(addM(at, 1).getTime() + 2 * DAY));
  }
  // Gina: Rust, declined once then recovered via admin Renew now (card) 2 days late.
  {
    const start = ago(48);
    const s = await server({ user: gina, host: "gina-rust", plan: pro, game: rust, created: start, exp: addM(start, 2) });
    const due = addM(start, 1);
    await audit(gina.id, "billing.card_declined", `${s.id}: attempt 1 for $18.99 — Your card has insufficient funds.`, new Date(due.getTime() + 600_000));
    await renew(s, "Rust — 8 GB / 50 slots", 1899, due, new Date(due.getTime() + 2 * DAY), 1899, true);
  }
  // Hank: game due 3 days ago, declined once — pending in dunning.
  {
    const start = addM(ago(3), -1);
    const s = await server({ user: hank, host: "hank-mc", plan: standard, game: mc, created: start, exp: ago(3) });
    await audit(hank.id, "billing.card_declined", `${s.id}: attempt 1 for $8.99 — Your card was declined.`, new Date(ago(3).getTime() + 600_000));
  }
  // Jun: annual Pro VPS (wallet covers), renews in 18 days. Kim: VPS, no card, wallet short, renews in 6 days (AT RISK).
  await server({ user: jun, host: "jun-annual", plan: starter, created: addM(ahead(18), -12), exp: ahead(18), term: 12 });
  await server({ user: kim, host: "kim-vps", plan: standard, created: addM(ahead(6), -1), exp: ahead(6) });
  // Leo: two new game servers — one auto-renew off (renews in 12 days), one on (25 days).
  {
    const s1 = await server({ user: leo, host: "leo-valheim", plan: standard, game: valheim, created: addM(ahead(12), -1), exp: ahead(12), autoRenew: false });
