  {
    const start = addM(ago(3), -1);
    const s = await server({ user: hank, host: "hank-mc", plan: standard, game: mc, created: start, exp: ago(3) });
    await audit(hank.id, "billing.card_declined", `${s.id}: attempt 1 for $8.99 — Your card was declined.`, new Date(ago(3).getTime() + 600_000));
  }
  // Jun: annual Pro VPS (wallet covers), renews in 18 days. Kim: VPS, no card, wallet short, renews in 6 days (AT RISK).
  await server({ user: jun, host: "jun-annual", plan: starter, created: addM(ahead(18), -12), exp: ahead(18), term: 12 });
  await server({ user: kim, host: "kim-vps", plan: standard, created: addM(ahead(6), -1), exp: ahead(6) });
  // Leo: two new game servers — one auto-renew off (renews in 12 days), one on (25 days).
  {
    const s1 = await server({ user: leo, host: "leo-valheim", plan: standard, game: valheim, created: addM(ahead(12), -1), exp: ahead(12), autoRenew: false });
    await audit(leo.id, "server.autorenew_toggle", `${s1.id} -> false`, ago(4));
    await server({ user: leo, host: "leo-mc", plan: standard, game: mc, created: addM(ahead(25), -1), exp: ahead(25) });
  }
  // Erin: hosting, renewed twice from the wallet, next in 5 days with a short wallet (at risk).
  {
    const start = addM(ahead(5), -3);
    const h = await db.hostingAccount.create({ data: { userId: erin.id, hostingNodeId: node.id, planId: hStarter.id, username: "erinsite", primaryDomain: "erin-bakery.com", status: "ACTIVE", diskQuotaMB: 10240, maxSites: 1, maxDatabases: 2, createdAt: start, expiresAt: ahead(5) } });
    for (let k = 1; k <= 2; k++) {
      const due = addM(start, k);
      const at = new Date(due.getTime() + 4 * 60_000);
      await debit(erin.id, `Web Hosting renewal: Starter for erin-bakery.com`, 299, at);
      await invoice(erin.id, `Web Hosting renewal: Starter for erin-bakery.com`, 299, at, due, addM(due, 1));
      await audit(erin.id, "billing.renewed", `hosting ${h.id} erin-bakery.com $2.99 -> ${addM(due, 1).toISOString().slice(0, 10)}`, new Date(at.getTime() + 5));
