    await audit(erin.id, "billing.suspended_unpaid", `hosting ${h2.id} erin-shop.com`, ago(10));
  }
  // Frank: business email, 3 monthly renewals, next in 9 days (wallet covers).
  {
    const start = addM(ahead(9), -3);
    const e = await db.emailSubscription.create({ data: { userId: frank.id, domainName: "weber-law.de", emailPlanId: ePlan.id, status: "ACTIVE", createdAt: start, expiresAt: ahead(9), verified: true } });
    for (let k = 1; k <= 2; k++) {
