// Screenshots of /admin/analytics/renewals against the throwaway DB. Not committed.
import { chromium } from "playwright";
import { SignJWT } from "jose";
import { PrismaClient } from "@prisma/client";
import fs from "node:fs";

const BASE = "http://localhost:3179";
const OUT = "/root/agent-notes/portal-batch-1007/renewals";
fs.mkdirSync(OUT, { recursive: true });
if (!/\/nxeon_pb1007(\?|$)/.test(process.env.DATABASE_URL ?? "")) throw new Error("not the throwaway DB");
const db = new PrismaClient();
const admin = await db.user.findFirst({ where: { role: "ADMIN" }, select: { id: true, sessionVersion: true } });
await db.$disconnect();
const token = await new SignJWT({ sub: admin.id, sv: admin.sessionVersion ?? 0, typ: "session" })
  .setProtectedHeader({ alg: "HS256" })
  .setIssuedAt()
  .setExpirationTime("1h")
  .sign(new TextEncoder().encode(process.env.AUTH_SECRET));
const cookieName = process.env.NXEON_COOKIE_NAME ?? "nxeon_session";

const browser = await chromium.launch();
const shots = [
  { name: "renewals-1440-dark", w: 1440, theme: "dark", path: "/admin/analytics/renewals" },
  { name: "renewals-1440-light", w: 1440, theme: "light", path: "/admin/analytics/renewals" },
  { name: "renewals-390-dark", w: 390, theme: "dark", path: "/admin/analytics/renewals" },
  { name: "renewals-390-light", w: 390, theme: "light", path: "/admin/analytics/renewals" },
  { name: "drill-failed-1440-dark", w: 1440, theme: "dark", path: "/admin/analytics/renewals?range=90d&drill=failed#drill", clip: "#drill" },
  { name: "drill-renewed-card-390-light", w: 390, theme: "light", path: "/admin/analytics/renewals?range=90d&drill=renewed&method=card#drill", clip: "#drill" },
  { name: "renewals-12m-month-1440-dark", w: 1440, theme: "dark", path: "/admin/analytics/renewals?range=12m" },
];
for (const s of shots) {
  const ctx = await browser.newContext({ viewport: { width: s.w, height: 900 }, deviceScaleFactor: 1 });
  await ctx.addCookies([{ name: cookieName, value: token, domain: "localhost", path: "/", httpOnly: true }]);
  await ctx.addInitScript((t) => {
    try {
      localStorage.setItem("nxeon.admin.theme", t);
    } catch {}
  }, s.theme);
  const page = await ctx.newPage();
  const res = await page.goto(BASE + s.path, { waitUntil: "networkidle", timeout: 240_000 });
  await page.waitForTimeout(1200);
  const status = res?.status();
  const h1 = await page.locator("h1").first().textContent().catch(() => null);
  const overflow = await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
  if (s.clip) {
    await page.locator(s.clip).screenshot({ path: `${OUT}/${s.name}.png` });
  } else {
    await page.screenshot({ path: `${OUT}/${s.name}.png`, fullPage: true });
  }
  console.log(s.name, status, JSON.stringify(h1), "hOverflow=", overflow);
  await ctx.close();
}
await browser.close();

